/* 平成20年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h20.committeeSessions.push(...[{"id":"h20-20081126-7","meetingId":"h20-cm11","date":"2008年11月26日","dateIso":"2008-11-26","committee":"厚生委員会","time":"午前１０時０２分～午後０時３０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１、請願・陳情審査","agenda":"の１、請願・陳情審査","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"ご説明をいただいたんですけれども、請願事項の１点目は、保護者補助金の所得制限の緩和ということで、所得制限のところを伺いたいと思います。","respondent":"小林保育課長","answer":"それから補助金の流れというお求めですけれども、こちらの補助金の開始年度は、保護者補助金が昭和４４年、就園奨励費は昭和４７年ということで、かなり長く維持されている制度ですが、あえて言いますと、大きく転機になったのは、平成８年に保護者補助金の制度にかんがみて。","voiceIndex":6,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"所得制限にひっかかってしまう方というか、この制度が受けられない方が１,５８６人保護者補助金のほうでいらっしゃるということなんですけれども、これが受けられない場合の、ここに所得制限の格差を緩和してくださいということなので、公立の幼稚園と比較をしてどのくらい負担が増えているのか、その差を教えていただきたいと思います。公立の保育料との差をもう１回教えてください。","respondent":"小林保育課長","answer":"公立との保育料の負担の状況というのは、園によって、また状況によってまちまちですので、代表的な例ということでご勘弁をいただきたいと思いますが、第１子の基本的な就園奨励費ないしは保護者補助金を受ける場合。","voiceIndex":8,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"園によって違うので、受けられていない方のその辺の幅というのか、保育料というか、一番高いところは幾らぐらいかかるんでしょうか。","respondent":"小林保育課長","answer":"平均の保育料ということでしょうか。","voiceIndex":10,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"園によって違いがあると思うので、例えば高い園の場合の保育料というのはどのくらい、そこで所得制限がかけられない方がどのくらい負担しているのかなということを知りたいのであって、すいません。そこを教えてください。","respondent":"小林保育課長","answer":"各園の保護者の負担ということかと思いますけれども、保育料は園によって違いますけれども、おおむね平均で月２万６,０００円限度が負担の中心になっていると、それ以外に教材費、あるいはその他の施設の費用等の負担が発生していると聞き及んでおります。","voiceIndex":12,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"預かり保育は本当に付加をして、特別のサービス的に考えないとやっていかれないような感じで、かなり赤字の中でやっていらっしゃるというところにおいては、この辺の考えというんですか、若干増えてはいると思うんですけれども、私はまだまだ不十分であると思うんですけれども、その辺のお考えはいかがでしょうか。","respondent":"小林保育課長","answer":"母の会連合会というのは、各園の私立幼稚園の中におられる保護者の方で母の会を組織して、その母の会が各園一緒に動いて事業等をやるということで連合会を組織している、いわば、私立幼稚園に対して幼稚園協会ということで幼稚園が連携しているわけですけれども。","voiceIndex":14,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"詳しくありがとうあります。預かり保育のところの都の補助金のところを知らなかったので、どのくらいの金額が出ているのかを教えていただきたいのと、すいません、保育園ＰＴＡのところの予算があったら教えてください。","respondent":"小林保育課長","answer":"それから都の補助金につきましては、今、つかんでおりますのは、私立学校経常費補助金、教育振興事業補助金の中の預かり保育ということで、１,６００万円ほどが、対象としては１８園に支給されていると聞いております。","voiceIndex":16,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"意見","question":"わかりました。預かり保育については都の補助金が若干出ているということで、これは助かるなと思うんですけれども、今、幼稚園のところでも、働きに出られるお母さんは増えているので、預かり保育は本当に需要が高くなっているので、ぜひこの辺の補助金も上積みができたらいいなと思って、これは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-007"},{"speaker":"渡辺委員","kind":"質問","question":"２番目の、今もありました母の会連合会の助成というところで、母の会連合会を含めて、振興費の補助金のところで、ここ数年の予算の増減の経緯を伺いたいのが１点、それはなぜかというと、この請願の趣旨の中ですごく強調されている思いの中で、地域の交流活動、そういった今、近年の社会情勢も踏まえて、この辺の変化というのはだれもが感じている中で、やはり親御さん、保護者の方の情報を得る場。","respondent":"小林保育課長","answer":"それから２点目の保護者の方が連携し、ないしは地域と連携していくことの大切さは委員がご指摘のとおりなんですが、そういった活動に使われる予算といたしましては、正確に把握してございませんが、母の会の活動、あるいは各園での保護者会等の活動、そしてまた昨年来。","voiceIndex":20,"id":"exchange-008"},{"speaker":"渡辺委員","kind":"質問・要望","question":"要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-009"},{"speaker":"阿部委員","kind":"質問","question":"手短に２点ほど伺います。それが１つです。それから母の会連合会への助成金、今、協会に内包された形であるので、協会への補助金の中から出ているというご説明だったかと思うんですけれども、これは話の順序としては、母の会に対する補助金がないからそうせざるを得ないという状況にあるのではないか、そのように理解したんですが、どのように受けとめていらっしゃいますでしょうか。","respondent":"小林保育課長","answer":"それから母の会の補助金につきましては、母の会単体では独自の事業形成をするにはまだ至っていないと思っておりまして、そういった意味では、協会の中でいろいろな活動をしていく部分につきまして。","voiceIndex":23,"id":"exchange-010"},{"speaker":"阿部委員","kind":"質問・要望","question":"それと、母の会単体では補助金の受け手としてどうかということだったと思うんですけれども、むしろこの組織を育てていくという意味でも、いきなり自立して全部自分でやれということではないにせよ、この母の会というものが組織としてさらに力をつけていくためには、項目として、まず母の会に助成金を出すという形で、少しずつ組織としての自立性を高めてもらう、そういう誘導をしていくという、当然。","respondent":"小林保育課長","answer":"それから母の会の育成という点では、保護者と園との協働・連携によって子供を育てていく、そういった意味での連携や地域との連携が大切という意味では、団体の育成ということは今後重視していくべき視点かと考えております。","voiceIndex":25,"id":"exchange-011"},{"speaker":"阿部委員","kind":"質問・要望","question":"ただ、特に私立幼稚園は、保育料だけではなくてさまざまな経費がかかってくる、かつ、幼稚園の場合、小さいお子さんを複数抱えたご家庭も多いということで、それに対する補助も既に新設されているところではありますが、やはり所得制限がかかったぎりぎりのところでの格差感ですとか、それから、あと公立では当然ながら所得による保育料の違いがないということなども考えますと、やはり実質的な負担。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-012"},{"speaker":"浅野委員","kind":"質問","question":"１番目の保護者補助金の所得制限の緩和について、基本的なところ、私が理解していないところをお伺いしたいと思うんですけれども、所得制限の導入以来、負担の格差が拡大しているという文言ですけれども、導入以前というのはどのような状況だったのか、例えば公立の費用と、あと私立の費用というのはどういう状況だったのかということ、補助の度合いですね、そしてこの所得制限が入ったときに。","respondent":"小林保育課長","answer":"所得制限につきましては、保護者補助金について所得制限が導入されましたのが平成８年当時と考えております。","voiceIndex":28,"id":"exchange-013"},{"speaker":"浅野委員","kind":"質問・要望","question":"また幼稚園そのものですけれども、やはり小学校、中学校が義務教育ということで基本的に無料という、全部が無料というわけではないですけれども、そういう形になりつつある中で、就学前のお子さんたちにも負担を減らしていこうという動きが当然あるわけでありますので、ここら辺をかんがみながら、ある意味ではバランスのとれた形で、これからもこういうことは進めていっていただきたいと思うんですけれども。","respondent":"小林保育課長","answer":"ただ、基本的には、今、委員がご説明、ご意見いただきましたように、それぞれの園の教育方針が第一、また、毎日のことなので、住まいしているところのアクセスの状況等が大きなファクターになっているのかと思います。","voiceIndex":30,"id":"exchange-014"},{"speaker":"浅野委員","kind":"質問・要望","question":"そういう形で、さっきもお話しさせていただきましたとおり、やはりそれぞれのさまざまな考え方で幼稚園に入れられているということと、保護者の負担をできるだけ減らしていくということはこれからの趨勢だと思いますので、ぜひともこの件につきまして、バランスのとれた形で進めていっていただければと思いますので、これは要望になります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"保護者補助金の所得制限なんですけれども、平成８年から導入したということなんですけれども、この導入した考え方というのがどういうことで導入されたのかということを１つ教えていただきたいのと、あと、毎年この請願は上がっていますので、去年の議事録でも私立幼稚園の保育料というのが毎年３.２％から５％上がっているというふうなことが課長の説明の中にあったんですけれども、そういう点でいえば。","respondent":"小林保育課長","answer":"所得制限導入の考え方というのは、当時の新聞記事によりますと、一律の所得制限もなく、一律の支給は制度の想定しないところであり、むしろ不平等であるというような指摘もありというようなことで書かれておりますが、その趣旨というのは、先ほどご説明しましたように。","voiceIndex":33,"id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"多くの区が所得制限をつけないというふうなところでやっているというところなんですけれども、私は、ここの請願では所得制限の緩和をぜひしていただきたいというふうなことですので、先ほどからご答弁いただいているように、２人子供がいて４人家族で７３０万円といったら、本当に生活としては、決して所得制限を設けなければならない、そういうレベルではないと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-017"},{"speaker":"堺委員","kind":"意見","question":"同じく、本日結論を出すということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"自民党としまして、ＰＴＡの方の保護者の方たちのお話もじかにお聞きしておりますし、また幼稚園からもいろいろなお話も聞いております。ただ、品川区としまして既にいろいろな対応はしている、そのことは我々も十分承知しておりますので、そのご要望の趣旨を採択したいということで、趣旨採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-019"},{"speaker":"堺委員","kind":"質問","question":"公明党も、今のこの件につきましては、我々もいろいろな機会に関係者からもお話を伺っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"生活がきびしくなっている中で、教育費が生活費を圧迫しているという、ここにも書かれていますが、十分理解をします。預かり保育の支援とか、保護者の皆さんの交流とか啓発を深めていくという意味でも、母の会への支援もご努力していただきたいなと、趣旨採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-021"},{"speaker":"阿部委員","kind":"意見","question":"所得制限については、７３０万円という数字がいろいろ見方が分かれる数字だろうなと思います。ただ、ここで切るということではなくて、やはりもう少し公平感を感じられるような段階的な緩和ですとか、そうしたことも含めて今後も研究・検討をしていただければと思います。全体としては、趣旨採択ということでお願いしたいかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今回、請願を出されたこの求める会の皆さんは、何年か前に都南病院跡地に特別養護老人ホームをつくってほしいという請願を出されて、６,５００筆ぐらい署名を集められて請願を出された皆さんなので、本当に身近なところに特別養護老人ホームをつくっていただきたいという強い願いを持っていらっしゃる皆さんで、特別養護老人ホームはかなわなかったけれども、高齢者施設ができるということで。","respondent":"冨岡高齢福祉課長","answer":"それから５月の国の考え方で、すべて軽費老人ホームというところで扱っていこうというふうになっておりまして、それは要は軽い費で、それは軽費老人ホームです。","voiceIndex":53,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"意見","question":"ということは、補足給付が入っているところで、特別養護老人ホームの４段階以上の人はちょっと難しいけれども、３段階から２、１という人たちは国民年金で特別養護老人ホームが利用できるということは、さっき、ほかの軽費老人ホームの説明とか、あと高専賃とか高優賃と特定の施設をプラスした施設、そういったところが特別養護老人ホームのように介護も受けられる施設だと。","respondent":"冨岡高齢福祉課長","answer":"そういう意味のサービス費をどうとらえていくかといったことも含めますと、６万６,０００円ということはとてもおさまりきかないという内容です。","voiceIndex":55,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問","question":"私は軽費老人ホームの中にケアハウスが含まれているという認識がなかったので、インターネットで見てみたら、軽費老人ホームとは、ケアハウスとはといって、こういうふうに書いてあったので、ここも教えてほしいんですが、身寄りのない、または家族との同居が困難な方々に低額な料金でご入居いただける、老人福祉法に基づく老人福祉施設ですということで、６０歳以上の方。","respondent":"冨岡高齢福祉課長","answer":"今回の部分につきましては、今後の高齢者の多様なニーズにおこたえするということの長期基本計画の中の一番最初の部分で位置づけて展開をしているというところで、時代時代を反映した対応ということで、名前的には似ておりますので。","voiceIndex":57,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私の疑問には、あまり軽費老人ホームのことがよくわからないんですが、都南病院のケアハウスを利用しての今回の高齢者の施設なんですけれども、ここへの助成というかの制度がどうなっているのかを教えてほしいのと、あと、課長は大体２０万円前後とこの間、ずっとおっしゃっていらして、前回ですか、厚生委員会のときに私たちが大起エンゼルヘルプのところの資料。","respondent":"冨岡高齢福祉課長","answer":"このさらに詳細な数値につきましては、年が明けまして１月の委員会で、今度は入居の募集をするわけですので、そのときにはご説明ができるかなと思っているところです。","voiceIndex":59,"id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問","question":"さっきの質問の中で、ケアハウスに対する助成の中身を教えてほしいんですが。","respondent":"冨岡高齢福祉課長","answer":"ケアハウスにつきましては、国から建設費の助成が出ているところです。","voiceIndex":61,"id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"その建設費の助成が、都南の場合、幾らなのかということを教えてほしいのと、原小学校跡のこうほうえんのところの家賃助成のところなんですけれども、東京都の家賃補助と品川区助成に基づく法人独自の家賃軽減制度、この中身が、これは受けられる助成の金額というのは一律なのか、何かランクがあるのかどうか、これって協定がつくられるということですか。","respondent":"冨岡高齢福祉課長","answer":"これにつきましては、Ａタイプで５万円、Ｂタイプで１万円という形の助成をするということで協定を調整しています。これはケアハウスはちょっと今、手元に資料がございませんが、高齢者施設ということで、全体で国から７,７５０万円ということで入っております。","voiceIndex":63,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"こうほうえんのところは、かなり東京都とまた独自の家賃軽減制度がついているので、この辺も大変大きいなと思うので、でも、これでもまだ国民年金では入れる金額では、Ａタイプの一番負担が少ないところで１４万１,２００円ということですけれども、でもかなり工夫をすると、いろいろなところで家賃の助成ができるなという、新しい試みというか、ケースであるなと思いますけれども。","respondent":"木下福祉高齢事業部長","answer":"それで、介護保険の中では基本的には介護保険の介護報酬を事業者としては収入として得るわけですが、利用者の負担金と介護報酬の部分で収支差額が出てまいりますので、今、厳しいという状況はありますけれども、収支差額が出てまいりますので、それが本来的には積み立てられて。","voiceIndex":65,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった面で、差のところを埋め合わせるような、私は例えば家賃助成とか、独自のものを考えていただきたいなと思うんですが、いかがでしょうか。","respondent":"木下福祉高齢事業部長","answer":"その結果、かなり低廉な利用料金の施設の提供ができたと考えていますので、現時点でのこの考え方で進めていきたいと考えています。","voiceIndex":67,"id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問","question":"逆に１点お聞きしたいのは、八潮南中学校のこれからの考え方の中で、跡地ですね、我々としては数多くの方が安い金額で入れる施設にしてほしいという、特別養護老人ホームという思いがありましたけれども、ある程度、今、区の方向性が出てきた中で、これから先、完成した時点で、概算で結構なんですけれども、どのぐらいで向こうを直したときに可能なのか、というのは。","respondent":"冨岡高齢福祉課長","answer":"それで、従来型個室ということで計算しますと、それがそっくり今後のになってまいりますので、今おっしゃった額で、利用者は２段階では４万円という、これは居住費全部含めて、粗い数字ですけれども、多床室だと３万７,０００円。","voiceIndex":69,"id":"exchange-031"},{"speaker":"阿部委員","kind":"質問・要望","question":"ちょっと教えていただきたいんですが、特別養護老人ホームの場合、ざっくりで構わないんですけれども、所得があまり高い方は逆に事実上、入れないとよく聞くんですが、大体どのくらいまでの方が入れているんでしょうか。","respondent":"冨岡高齢福祉課長","answer":"実態的には、やはり一番、第１段階の方が２割、３割ということで、そちらのある程度所得的には低い方が現実的には多くなっているです。","voiceIndex":71,"id":"exchange-032"},{"speaker":"阿部委員","kind":"質問","question":"当然、こういう低所得の方が入れる特別養護老人ホームなども用意しておかなきゃいけない。どれも増えていかなきゃいけないと思うんですけれども、今後、そのバランスというんですか、特別養護老人ホームはまだこのくらい欲しいとか、もうちょっと中堅層に対しての施設をこのぐらい欲しいとか、きっちり数字で出さなくても、今後の考え方みたいなものを教えていただけないですか。","respondent":"木下福祉高齢事業部長","answer":"そういう点でいくと、いい適地があったときに、どの制度を使ってやっていくのがいいのかということを具体的に精査して考えていくほうがいいだろうと思いますので、長期的に何カ所という、どちらを幾つずつというようなことをお話しするよりは。","voiceIndex":73,"id":"exchange-033"},{"speaker":"浅野委員","kind":"質問","question":"そういう中で、例えば今回の請願にあります、端的に聞きますけれども、国民年金でも入れるような利用料というのは、このような建て方をした場合は、制度をいろいろなことを駆使しても全くだめなのかということを１点お伺いしたいのと、逆に、今、部長からもお話があったとおり、そのような国民年金でも入れるような利用料を設定できる施設というのはどのような建て方、今。","respondent":"冨岡高齢福祉課長","answer":"それにつきまして、今の特別養護老人ホーム以外の制度を利用して、別の形であれ、施設をつくるとなると、その分を国民年金の程度の利用料にするということは財源の投入をしない限り無理ですので、施設的には難しいと考えております。","voiceIndex":75,"id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"何点かお聞きしたいんですが、まず、この都南病院跡地の高齢者施設は来年の４月からオープンになると思うんですけれども、原小学校の跡地は３月からということで１１月１１日から申し込みが始まりましたけれども、都南病院跡地の高齢者施設の申し込みというのは、１カ月おくれたから１カ月おくれで１２月からというわけじゃないんでしょうか。その点、３点お願いします。","respondent":"冨岡高齢福祉課長","answer":"その後に、１月２１日ので出せれば広報で出して、申し込みのご案内をしたいと思っていますので、一定期間を置いて、２月ぐらいには申し込みというような、詳細についてはまだこれからですけれども、そういうふうなスケジュールで進めたいと考えています。","voiceIndex":77,"id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうところで、区としてはニーズにこたえて、これからもケアホーム、高い利用料の施設をつくっていくというふうなことで言われていますけれども、私はどこでどんなニーズというふうなところが、こういうふうなケアホームのどんどん建てていくということになっていくのか、そのニーズの裏づけというのは何なのかということを１つ教えていただきたいと思います。","respondent":"冨岡高齢福祉課長","answer":"お申し込みの早いものですから、一応見込みでその部分についてはとりあえず発車をしていると、助成の額についてはそういう流れです。","voiceIndex":79,"id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は特別養護老人ホームが４９２名も申し込みながら、西五反田のケアホームは３０人ぐらいしか申し込めないと、五、六パーセントの人しか申し込めないという区民の実態の中で、区がニーズにこたえてケアホームをつくっていくんだというふうなことでずっと言われているわけですけれども、そのニーズというのはどういうところから来ているのかという、そのニーズの裏づけを聞かせていただきたいと。","respondent":"木下福祉高齢事業部長","answer":"都南についてもできないのかというお話がありましたけれども、そういう意味で、都南についてもそのような形で区は建設費のかなりの部分を持って、事業主負担は年間でいうと大体５５０万円をちょうだいする金額にしておりますのは、国と都の補助金を除いた残りの金額。","voiceIndex":81,"id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そうしたらやっぱりＡタイプと同じぐらいの、同じ時期にできる、区民からすると本当に同じ施設なわけですから、同じ料金でなければ納得いかないと思うんです。いろいろのところで聞いてみてください。ケアホームと特別養護老人ホーム、どちらが希望ですかといったら、特別養護老人ホームを建ててくださいという人のほうが必ず多いですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"だから、その平均というふうなことからすると、２３万円なんていうのは本当に高いほうで、前に比べて厚生年金の人が多くなるというけれども、厚生年金の人の年金はどんどん下がっていますので、そういう実態ではないというふうなところも改めて考えていただきたいと思います。それと、先ほどの、そうするとケアホーム、原小学校の跡地の建設に……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-039"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう点でも、私は区民の圧倒的なニーズというのであれば、圧倒的なニーズは特別養護老人ホームをつくってほしいというふうなことだと思いますし、先ほど新型特別養護老人ホームは所得制限はありません、所得の高い人から、厚生年金の方から低い人までみんなが入れるのが新型特別養護老人ホームで、施設そのものもケアホームと基本的には同じですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-040"},{"speaker":"堺委員","kind":"意見","question":"本日結論を出すということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":90,"id":"exchange-041"},{"speaker":"鈴木（真）委員","kind":"意見","question":"自民党としましては、都南病院の跡地の高齢者施設についての利用料につきましては、再三低い金額でお願いをしたいということは何回も主張はしております。希望としては、私どもももちろん同じように安くということはわかっておりますけれども、この請願の国民年金者でも入れる利用料にしてくださいという部分につきましては、申しわけないですが、採択できないという考え方をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-042"},{"speaker":"堺委員","kind":"意見","question":"申し上げておきたいことは、公明党としても特別養護老人ホーム、あるいはこういうケアハウス等につきましても、高齢者施設、あるいは高齢者の方がご利用されるという視点からとらえますと、それは利用料が安いことにこしたことはないわけでありまして、なお、また希望としては、なるべくならば、利用者も安心して利用できるような料金設定にしてもらえるならば、なお一層ありがたいなとは思いますけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":95,"id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"有料老人ホームとか、ケアホームとかが経済的な理由で利用できない、施設は無理だということになると、介護難民がますます増えてしまう。この間、区民のニーズであるということでケアホームをつくってきた。もう現実的に進んでいる施設なので、今できる対策ということを具体的に考えていただいて、この請願に添うような状況に持っていっていただきたいなと思いますので、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-044"},{"speaker":"阿部委員","kind":"質問・要望","question":"前提として、高齢者のための施設が数として足りていないということはあると思います。国の施策が新しく出ると、それだけで設定できる利用料金というのは変わってきますので、そういった意味では区だけではなくて、国に対してももっともっと充実した施策をどんどん出してほしいと思いますし、それに対する研究というのも当然区でも続けていっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-045"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"川西絹子議員の高齢者住宅の建設促進についてというところのご答弁の中に、小規模多機能に付属してというか、つけて高齢者の住宅を考えるといったご答弁があったかと思うので、ちょっとその辺を詳しく、メモが見つからなかったので、申しわけないんですが、その辺をもう一度というか、ご答弁をいただきたいのと、高齢者住宅に関して、今後、期待できるというか。","respondent":"永尾高齢事業課長、冨岡高齢福祉課長","answer":"高齢者人口は増加しておりまして、今後、そういう方に対しての体制、新しい高齢者住宅を建設していくことについて、今、検討をしていますが。今の小規模多機能型居宅介護施設ということで、併設ですが、これはあくまでも「など」というふうに書いてありますように、そういう介護施設を代表として申し上げたということで、併設を検討していると。","voiceIndex":101,"id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"まだこれからというところの受けとめなんですけれども、高齢者住宅というのがどういう中身なのかというあたりを、わかっていることをもうちょっと伝えることができるんだったら教えてほしいのと、これから取得というところでは、今後の経緯のめどというか、どのくらいまでにはという考えがあるのかどうか、その辺も聞かせてください。","respondent":"永尾高齢事業課長","answer":"それと、あと今後の予定については、現在、土地の候補として都営大井林町跡地を考えているんですが、こちらにつきまして、まだ取得のめどは立っていない状態であります。ですので、この土地の取得が決定いたしましたら、検討に入っていきたいと考えております。","voiceIndex":105,"id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問・要望","question":"高齢者住宅は本当に希望者が多いので、頑張って進めていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-048"},{"speaker":"鈴木（真）委員","kind":"質問","question":"先ほど希望の中で２階以上が多いと言ったんですが、高齢者の方は２階以下だよね。そこがちょっと気になった。私もここは何回か質問しているので、同じような話なんですけれども、お願いします。","respondent":"永尾高齢事業課長","answer":"申しわけありませんでした。２階以上は希望しないです。どうも失礼いたしました。","voiceIndex":108,"id":"exchange-049"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"高齢者住宅なんですけれども、２１９戸と同じような高齢者住宅という、シルバーピアの高齢者住宅と考えていいんでしょうか。高専賃とか、そういうものではなくて、シルバーピアの今までずっと、今、１２月１日から５日まで募集が始まりますけれども、その高齢者住宅が増える、その高齢者住宅を増やすという考え方でいいのか、そこだけ確認させてください。","respondent":"永尾高齢事業課長","answer":"高齢者住宅としての考え方は今までと同様ですけれども、制度の使い道として、高優賃を使うなどのことを今現在考えているところです。","voiceIndex":110,"id":"exchange-050"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"高優賃というと、近傍家賃の設定というふうなことになってきますよね。そこら辺のところが、私はぜひ所得の少ない人が対象になるような、今までの高齢者住宅を拡大するという形での検討をぜひ、要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3222#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":37706,"voices":121}},{"id":"h20-20081126-8","meetingId":"h20-cm11","date":"2008年11月26日","dateIso":"2008-11-26","committee":"建設委員会","time":"午前１０時０２分～午後２時２４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菊地委員","kind":"意見","question":"工事箇所の端から５０ｍというと、平成１８年のとき、トンネル工事の全線片側５０ｍに配布をしたという話があったんだけれども、ちょっとそこをもう少しお聞かせ願いたいというのと、それから、さっき以前に八潮での説明があったというお話だったんだけれども、今回の中身とはまた若干違うのかなというふうに思うんだけれども、実際に工事そのものについて言えば、あそこから土砂が搬出をされるということで。","respondent":"梶都市計画課長","answer":"今回に関しましては、実際にあそこの大井北立坑のほうからシールドマシンは進んでまいりますので、今度はその掘進工事が始まりますということで、実際にこの下を通っていきます沿道の方々にご説明を行う、そういった説明会です。","voiceIndex":7,"id":"exchange-001"},{"speaker":"菊地委員","kind":"意見","question":"そうすると、前回八潮でやった説明会の内容が今回の説明会で行われる。ほぼその内容が行われるんだということで解釈していいのか。それともう一つ、さっきの５０ｍは、正確に言うと、トンネルを中心にして１００ｍの範囲に配布をされたということでいいんですよね、多分。","respondent":"梶都市計画課長","answer":"八潮でこの間説明された内容と同じものかといったご質問ですが、八潮で説明されたものは、先ほど説明したとおり国道のほうに抜けるトンネルがあります。そちらのほうをあわせて説明させていただきました。","voiceIndex":9,"id":"exchange-002"},{"speaker":"菊地委員","kind":"質問・要望","question":"もう一回お聞かせ願いたいんですけれども、前区長の時代に区からもこの中央環状線について、要望が上げられていましたけれども、この辺の要望というのは、実際にどの程度都でも組み入れて工事計画が進んでいるのか、そこをちょっともう一点だけお聞かせ願いたい。","respondent":"梶都市計画課長","answer":"それにつきましては、工事に関しましては、地元の住民の方々に丁寧な説明をして、それで行っていただきたいというのが１点。そしてまた、いろんな不安を取り除くために最新の設備で実施されたいという点です。","voiceIndex":11,"id":"exchange-003"},{"speaker":"菊地委員","kind":"質問・要望","question":"前区長の時代に出された要望の中の一つとして脱硝装置の問題、新宿線につけられている脱硝装置、今課長のお話だと最新のものをというお話だったんだけれども、いよいよシールド工事が始まる段階でもって、東京都の見解というのは、以前と変わっていないのかどうかというのをお聞かせ願いたい。","respondent":"梶都市計画課長","answer":"今言われた脱硝装置につきましては、我々のほうといたしましては、最新のものをという話をさせていただいてあります。東京都のほうは、脱硝装置につきましては、平成２２年までに結論を出したいという形で今検討中と聞いてあります。","voiceIndex":13,"id":"exchange-004"},{"speaker":"原委員","kind":"質問・要望","question":"１点だけ。返事は要りません。要望です。地域住民への丁寧な説明ということについて、先ほどご説明が５０ｍ、５０ｍということで１００ｍということなんですけども、配布されていない地域があるというようなことも私のところに上がってきておりますので、地域にまた丁寧な説明をするように再度申し入れを、ということだけ要望として言っておきます。お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-005"},{"speaker":"石田（慎）委員","kind":"質問","question":"今のとちょっとかぶるんですが、今回は１万８,８００枚配布されたということなんですが、以前にも説明会をやられていると思うんですが、そのときの枚数というのがもしわかれば教えてほしいんですが。","respondent":"梶都市計画課長","answer":"前に、この沿線で説明したときは、事業説明会という形で工事の事業の説明ということですが、こちらのほうも５０ｍの範囲で行ったという話を聞いているんですが、配布枚数のほうは、手元に資料がございませんので、申しわけないんですが、大体同じだと考えています。","voiceIndex":16,"id":"exchange-006"},{"speaker":"石田（慎）委員","kind":"質問","question":"丁寧な説明会をということであれば、本来前回以上の枚数が配られるのが、丁寧な周知の仕方なのかな、より幅広く周知をしていくという話で上がっていくのかなと思うんですが、そういうと、５０ｍと決めているからずっとその５０ｍでいくのか、それとも、ある程度行って、幅を広げていくのかというのがもしわかれば教えてください。","respondent":"梶都市計画課長","answer":"ただいまのチラシの配布の箇所という形ですけれども、こちらの場所は、例えば立坑とかそういった形で、上に塔が建つとか、そういったものにつきまして、また高さの倍の範囲に配るとか、そういった考え方をしていますけども、今回この説明会につきましては。","voiceIndex":18,"id":"exchange-007"},{"speaker":"井上委員","kind":"質問","question":"先ほど町会のほうに周知の方法を含めて案内をしているということだったので、そこのところはどういうふうなお話をされているのかということが一点と、平成２１年の１月と平成２２年の１月というところの説明をちょっと聞き落としてしまいましたので、そこをもう一点お願いしたいことと、実際にシールド工事が始まるということで、今までは計画だけだったんですが、着手に当たって、結果的に８km。","respondent":"梶都市計画課長","answer":"そこから東京都立みなとが丘ふ頭公園の先で北上、補助２８号線を通って北上いたしまして、北部陸橋のところから大井北立坑に入るというルートを予定しているということでございまして、つまり、八潮等の市街地は通らないということを聞いてあります。","voiceIndex":20,"id":"exchange-008"},{"speaker":"井上委員","kind":"確認","question":"そうすると、シールドの工事説明会はこの場所でも東京都が１年おくれで始まりますよということで説明が終わって、東京都が始まるときの説明会はもうしないのかどうか。１年先ですから、しないのかどうかということの確認と、それから結果的に土砂は東京湾の埋め立てに使うのか、そうではなくて、他府県に行くのか、そこら辺はわかりますか。","respondent":"梶都市計画課長","answer":"もう一点です。今回は来年の１月の説明会という形なんですけど、今回、こちらのチラシにも書いてありますとおり、東京都のほうの担当と、そして首都高速道路の担当と、両方の担当がまいりますので、こちらで両方の工事説明会をすると考えております。","voiceIndex":22,"id":"exchange-009"},{"speaker":"井上委員","kind":"質問","question":"さっき抜けてしまったんですが、東京都は海のほうからの経路で土砂を運ぶことも検討中ということなんですが、東京都がというと、首都高速とは別なんですか。結果的に首都高速がやっている工事の土砂も東京都の土砂も一緒に処理するのか、それともそれぞれが処分するのか。","respondent":"梶都市計画課長","answer":"ちょっとわかりにくい説明で申しわけございません。この土砂の運搬ですけれども、シールドマシンの掘進の掘削の作業なんですけども、１年間ずれがあります。こういう形で最初首都高速でやる場合についてはもちろん陸路を考えてあります。","voiceIndex":24,"id":"exchange-010"},{"speaker":"井上委員","kind":"提案","question":"出たときにも提案をさせていただきましたけれども、やっぱり２２件をどう評価するかというのは別としても、期間の延長というか、要綱の中には３０日、１４日以上という最低のところが示されていますけれども、ここのところは意見をもらうという姿勢、最終的には区民との協働で。","respondent":"梶都市計画課長","answer":"ただいまのご質問です。１点目でございまして、パブリックコメントの実施される日数という形です。今後もまた素案等がありますので、日数等に関しましては、これからの検討課題とさせていただきたいと思います。","voiceIndex":31,"id":"exchange-011"},{"speaker":"井上委員","kind":"確認","question":"ということは、この景観計画に対して最終的には平成２２年の運用開始までこのアール・アイ・エーというところで進むということなのでしょうかということだけ、確認したいと思います。","respondent":"梶都市計画課長","answer":"ただ、こちらにつきましては、いろんな諸般の事情やいろいろこの業者と今まで詰めた経緯もありますので、そこら辺のことは加味しながら契約担当の課と相談をしてまいりたいと考えております。","voiceIndex":33,"id":"exchange-012"},{"speaker":"井上委員","kind":"質問","question":"単年度契約ということは、今年度の契約を入札でまたするとか、単年度契約で翌年に対してどういう判断でされるのかということと、今年度のコンサルタントの委託料、委託契約はどのぐらいで行われたんでしょうか。","respondent":"梶都市計画課長","answer":"原則といたしましては、区の契約ですので、こちらのほうは単年度契約で結んでおります。ですので、来年度につきましては、来年度の予算が確定した段階で検討するものと考えております。","voiceIndex":35,"id":"exchange-013"},{"speaker":"菊地委員","kind":"質問・要望","question":"一つだけ教えてもらいたいんですけれども、これから策定しようとする景観計画と景観行政団体になるということ、計画そのものは景観行政団体として認定されないとできない中身に含まれているのかなというふうに思うんですけれども、ちょっとその辺のところの関係を少し教えていただきたい。まだ景観行政団体として認定をされているわけではないんですから、その辺の関係をお願いします。","respondent":"梶都市計画課長","answer":"それで、案の段階で東京都のほうともう一度これでいいかどうかという話をいたしまして、合意をいただいてから景観行政団体になるという形です。景観行政団体になってから、初めて景観計画というものが皆様方にお示しできると、こういった流れです。","voiceIndex":37,"id":"exchange-014"},{"speaker":"菊地委員","kind":"意見","question":"素案という段階ではわかるんですけれども、実際にここでは平成２２年度から景観計画の運用を開始というふうに書かれているんですけれども、ということは、約１年間かけて東京都との協議は確実に整うんですよという前提ですよね、運用開始ということは。ちょっとその辺をもう少し。","respondent":"梶都市計画課長、岩田まちづくり事業部長","answer":"こちらのほうに、「今後の予定」と書いてありますとおり、私どもで粛々と今進めているところです。ただ、東京都は東京都のほうの考え方がございまして、そういった中で、今事前相談とか、そういう段階です。予定でいけば、平成２２年度当初からスタートをしたい、こういうふうに考えているところです。","voiceIndex":39,"id":"exchange-015"},{"speaker":"菊地委員","kind":"質問・要望","question":"拡大をされた中でまず個別の問題として今度住宅市街地のこの地区を追加していくという意味なんでしょうか。その辺のところがよくわからないので教えていただきたい。というのは、今回立会川駅周辺地区というのが削除されるようになりますけれども、これは豊かな住環境を目指す地区として設定されていたものが削除されるというのは、どういう意味があるのかという、ちょっとその辺を教えていただきたい。","respondent":"梶都市計画課長","answer":"ただいまのご質問で、防災街区整備方針とのつながりですけども、これは東京都市計画でございまして、その中に書いてありますとおり、防災街区整備方針あるいは再開発整備方針等もあります。","voiceIndex":48,"id":"exchange-016"},{"speaker":"菊地委員","kind":"意見","question":"従来は重点地区だったわけですね、立会川駅周辺というのは。だから、じゃあ重点地区じゃなくなるというのは、まちが、ここでは「再開発事業の事業化の見通しがたたないため」と書かれているんだけれども、単純にこういうことだけで削除されていくような中身なのかどうかというのがよくわからないんです。その辺をもう少し。","respondent":"梶都市計画課長","answer":"その重点地区の選定基準なんですけど、５ページに書いてありますとおり、「重点地区には、住宅市街地の計画的な整備または開発に向けた都市計画の決定、あるいは事業等の実施等が見込まれるものを選定する」と書いてございまして。","voiceIndex":50,"id":"exchange-017"},{"speaker":"菊地委員","kind":"意見","question":"住宅密集地域でも、地域の改善、防災力の向上だとか、地域の改善という地域と、それから再開発地域がこうやって重複されて設定をされているというのは、住環境そのものでいえば、随分中身としては違う施策なんだと思うんだけれども、それが一つのこういう一括りの中で設定をされるというのは、どういう前提のもとに考えられているのか、その辺をちょっと。","respondent":"梶都市計画課長","answer":"そういった内容は、こちらの方針に入っていないと事業ができないという形ではないんですけれども、事業を実施していく上で、一番大きな、大まかな方針というのが決まってございまして、個々の事業というのは、またそれぞれ決まってくる内容であろうと考えています。","voiceIndex":52,"id":"exchange-018"},{"speaker":"井上委員","kind":"提案","question":"東京都の都市計画の変更ということで、その中で品川区の分がこれだけということだと思いますけれども、この経過というか、品川区が提案をして、ここを載せてくださいねというようなものなのか、その流れを説明していただきたいということと、あと５ページの選定基準のところ、先ほどの委員からも出ましたけれども、荏原地域、この間都市計画の防災のところで荏原地域が随分と拡大をされた計画になって。","respondent":"梶都市計画課長","answer":"今度は財政フレームを含めた考え方ということですけれども、この住宅市街地の開発整備の方針につきましては、大まかな方針とか方向づけをあくまでも示したものでございまして、財政的なもの、財政投資のフレームまで中に含んであるものではございません。","voiceIndex":54,"id":"exchange-019"},{"speaker":"井上委員","kind":"質問・要望","question":"最後の、ここに指定されたからということで、財源の問題はこれからということで、ここはわかったんですけれども、６月に縦覧というのは、エリアを拡大するときの縦覧の話だったと思うんですが、だから、ここのところ、そのエリアの中で重点地区にしたというところは、東京都が全体を見てこういうふうにしたんじゃなくて、品川区がここを指定してほしいんですけどという相談をされて。","respondent":"梶都市計画課長","answer":"事務的な話で申しますと、東京都の案の変更をいただいたときに、品川区のほうにご相談をというのがございましたので、その中で品川区としてそういった新しい地区と、そういったものについて出てきた案という形でご理解いただければと思います。","voiceIndex":56,"id":"exchange-020"},{"speaker":"井上委員","kind":"質問","question":"区としてここを重点地区に指定する、もっといっぱいあったはずですけれども、ここを推したということは、どういった計画とか考えを持ってここになったんでしょうか。","respondent":"梶都市計画課長","answer":"選定基準ですけども、そちらに書いてありますけども、事業等の実施が見込まれるものとか、実際に事業をやっているところがありますので、そういった面では先ほど言いました５つの地区というのは、これから品川区としてやっていく、あるいはやっているところもありますので。","voiceIndex":58,"id":"exchange-021"},{"speaker":"井上委員","kind":"質問","question":"９番のところで、大井町駅地区のところに２haの追加というふうにありますけれども、これはエリア拡大ということで、ここの部分も変更のところだと思うんですが、これはどういったことでしょうか。","respondent":"梶都市計画課長","answer":"そこの左下のところにちょっと出っ張っている部分がありますけども、そこのところ、大井一丁目南地区という形で、そこの補助１６３号線ですか、こちらの整備に伴いまして、再開発事業地区という形で、そこの地区が２ha追加になっているです。","voiceIndex":60,"id":"exchange-022"},{"speaker":"菊地委員","kind":"意見","question":"ちょっともう一点だけ。今までのお話でどうしても出てこないのは、そうすると、重点地区だよと設定をされた住民の皆さんのところへの、今区が考えるメリット、区のメリットというのは一体どこなのか。ただ、単純にこうやって並べたけれども、別に財政的にどうこうというのもないということだし、一つ考えるのはあくまでもそういう方針ですよね。どういう地域をつくろうかという決意。","respondent":"梶都市計画課長、青木都市開発課長","answer":"こちらのほうは方針という形で大まかな、大まかというと怒られるでしょうけど、全体的なものですけれども、これにつきましては、いろいろな事業を進めるときは、再開発事業など進めておりますけれども、そういった内容にする場合に。補足いたします。今、大井町駅前地区のところで、再開発事業を予定されている区域を今回の住宅市街地の開発整備の方針の重点地区に加えたというご説明を担当課長からしています。","voiceIndex":62,"id":"exchange-023"},{"speaker":"菊地委員","kind":"質問","question":"別紙２の変更後の荏原地区、５２２.５、単位はヘクタールですか。","respondent":"青木都市開発課長","answer":"すみません、ヘクタールです。","voiceIndex":70,"id":"exchange-024"},{"speaker":"菊地委員","kind":"質問","question":"ヘクタールですよね。従来、この三つをあわせると、約２２０haだったのをここまで再開発促進地区との整合を図って拡大したというんだけれども、防災再開発促進地区、拡大された地区全体に２号地区としての設定がかかったわけですよね。それがこの５２２.５haという意味なんですか。それとも、また別枠での設定の仕方ということなんですか。","respondent":"青木都市開発課長","answer":"防災まちづくりを進めたいという視点で地区の指定をしたのが防災街区の防災再開発促進地区という指定で、今回、先ほどもちょっと説明しましたけれども、都市再開発方針において、２号地区に指定されていることが再開発事業を行う場合の国庫補助採択基準になりますので。","voiceIndex":72,"id":"exchange-025"},{"speaker":"井上委員","kind":"質問","question":"今の防災再開発促進地域から２号地区に拡大して指定するというところで、再開発というイメージでは、これを縦覧したときに区民の皆さんにとってどういうふうなことが進んじゃうのかなという、再開発と聞くと、何かまちづくりみたいな、言葉をとるとそういうイメージで、ここのエリアが広いところ、すべてがそういうふうに誘導されていくのだろうかというような思いがあるんですけれども。","respondent":"青木都市開発課長","answer":"ただ、私ども品川区のまちづくりの考え方としまして、今回ここで言う荏原地区と呼んでいるところは、防災の安全性を高める必要があるということで、防災街区整備方針のほうで防災再開発促進地区に指定したものでございまして、再三申し上げますとおり、今回２号地区に指定すると。","voiceIndex":74,"id":"exchange-026"},{"speaker":"菊地委員","kind":"質問","question":"だから、日野学園がちょうど真ん中で、周りをぐるりと開発の中に囲まれちゃうことになるんだけれども、これはそういうものも、今建っているそういう大きなビルなんかも、入れた上での風環境による評価というふうになるんですか。","respondent":"青木都市開発課長","answer":"それと、大崎地区については、いろんな建物が今後も開発予定されているものがありまして、確定したものではないので、こういった説明会等ではご用意していませんが、行政の実務者としては東京都も含めまして。","voiceIndex":81,"id":"exchange-027"},{"speaker":"菊地委員","kind":"質問・要望","question":"日影図を見ると、日野学園そのものに一定時間かかるようになるんだけれども、周りをこういう形で囲まれることによって、隣に建ち上がる１６０ｍ級のビルですか、あれも含めて日野学園というのは、１日を通して日陰の状態というのがつくられてしまうことになっていくのかなと思うんですけれども、その辺での問題意識というのは区としてはどのように思っておられるのか、そこのところをお聞きしたいのと。","respondent":"青木都市開発課長","answer":"地区計画では、まず上位計画としまして、先ほども申し上げましたように大崎駅周辺が都市再開発方針の２号地区に指定されておりますし、その前提となります都市再生緊急整備地域に指定されているというエリアになっておりますから、ここは望ましい。","voiceIndex":83,"id":"exchange-028"},{"speaker":"菊地委員","kind":"質問","question":"ですからやっぱり、こういう状況というのをどれだけ改善できるのかよくわかりませんけれども、この計画そのものについてもやっぱり建物の配置、さっき日野学園側のほうに大きく土地を設けてやったという話があったけれども、さらなる改善というのは必要だろうなというふうに思いますので、これは意見として申し述べておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-029"},{"speaker":"井上委員","kind":"質問・要望","question":"今ちょっと要望というところであった部分と重なるんですけれども、事業者がここを開発するに当たっての計画を出されて、高さを見ると２２階建てだけれども、高さとしては１１５ｍ、この近隣で今計画されている超高層のビルが１５９ｍなんですけど、それ以外ではこれは高い建物というふうになると思うんですが、この計画があって、都市計画決定をする区として何か検討を要請したものとか指導というか。","respondent":"青木都市開発課長","answer":"昨日も別の案件のご報告のときにご説明申し上げましたけれども、大崎駅周辺地域については、建物の高さ等のデザインコントロールをまちづくり連絡会という地元の方々と区が一緒になって情報交換しています会議の中で。","voiceIndex":86,"id":"exchange-030"},{"speaker":"原委員","kind":"質問","question":"こちらの資料の２ページの中の計画概要の利便施設というものと、それからあと文化・情報発信施設、その辺についてもう少し詳しく教えてください。","respondent":"青木都市開発課長","answer":"ですので、そういった入れ物、例えば包むとか、囲むとかというようなテーマで、そういったものをつくって、そういった品物のありがたみというものを表現できたらいいなということでご検討いただいておりまして。","voiceIndex":88,"id":"exchange-031"},{"speaker":"原委員","kind":"質問・要望","question":"そうしますと、文化・情報発信施設ですが、地元の協議会ですとか、区のかかわり、これはあくまでも東洋製罐は非常に保守的というか、非常に固い企業だというふうに私は地元から聞いておりまして、かかわりなんですけど、区としての、かなり、こういう表現をしていいのかわかりませんけど、意見が通るのか通らないのか、交渉権があるのかないのかとか、というのは、非常に品川区というのは産業。","respondent":"青木都市開発課長","answer":"若干整備時期はおくれますけれども、北品川五丁目地区の再開発事業におきましても、交流施設等が予定されておりますので、そういったものの運営については区民の方々とのお話し合いの中で品川区も関与していって、より開かれたものとしてご活用いただけるように。","voiceIndex":90,"id":"exchange-032"},{"speaker":"原委員","kind":"質問・要望","question":"そうしましたらば、要望なんですけれども、今広げていただいたのでぜひともお願いしておきたいのは、このビルだけではなくて、その協議会のほうとも連動を持って、全体がつながり合えるような形でのまちづくりをお願いしたいなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-033"},{"speaker":"菊地委員","kind":"質問","question":"２棟の住宅でありますけど、何戸ぐらいの数なのか教えてもらえますか。","respondent":"青木都市開発課長","answer":"超高層住宅を予定していますけれども、住宅戸数等については事業者案としては約７００戸ほどを想定しているということで報告いただいております。","voiceIndex":97,"id":"exchange-034"},{"speaker":"井上委員","kind":"質問","question":"ここは、目黒区と隣接ということで、目黒区は高さ規制を設けてまちづくりを進めるといったときに、区としては、この辺のこと、こちらは品川区ですよと言っていくのか、その辺はどのように見解を持たれているんでしょうか。","respondent":"青木都市開発課長、岩田まちづくり事業部長","answer":"率直に申し上げまして、目黒区は目黒区、品川区は品川区で自立しております。その範囲内の絶対高さ制限を考えているということですから、こういった法定再開発事業、地区計画を立てて、都市計画の手続に基づいて行われるものについては、おおむね例外規定扱いされているというふうに理解をしております。","voiceIndex":99,"id":"exchange-035"},{"speaker":"三上委員","kind":"質問","question":"東急の駅ビルのところにも、目黒区が越境して行政サービスセンターをつくったりとかということになっているわけですけれども、そういった点で、せっかくこういう東京都交通局が持っているという土地でありますから、そういう意味にあっては、行政がやはり出張所的な機能というのは当然持ち合わせるべきではないかというふうに、だれが考えてもチャンスだということはあるわけで。","respondent":"青木都市開発課長","answer":"もともと再開発準備組合の皆様も先行まちづくりプロジェクト、東京都が関与するプロジェクトの中で、地元に還元されるものでありたいということから、積極的に子育て支援施設については自ら設置していく方向で考えているというようなお答えをいただいております。","voiceIndex":102,"id":"exchange-036"}]},{"id":"topic-02","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"１点、新聞報道で基本構想の目玉とも言える公園づくりの子どもたちの募集の件が報道されていまして、ちょっと要望もありますので、その部分での詳細というものをお話いただける範囲でお聞きしたいというふうに思います。","respondent":"松代管理工事課長","answer":"今後の予定としましては、今年度その４回の子ども会議で出された案を取りまとめまして、平成２１年度引き続きその内容をさらに実施すべく設計作業に入り、平成２２年度に工事にかかっていきたいというようなことで進めていきたいというふうに考えているところです。","voiceIndex":120,"id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3930#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":39188,"voices":123}},{"id":"h20-20081126-9","meetingId":"h20-cm11","date":"2008年11月26日","dateIso":"2008-11-26","committee":"文教委員会","time":"午前９時０３分～午前１１時４９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4652#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":3866,"voices":12}},{"id":"h20-20081126-5","meetingId":"h20-cm11","date":"2008年11月26日","dateIso":"2008-11-26","committee":"総務委員会","time":"午前１０時０２分～午前１１時１９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"１番目の品川区長期基本計画の策定状況","agenda":"１番目の品川区長期基本計画の策定状況","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"それで、策定委員会というのは多分２日にあって、そして２５日に答申を出していただくというふうに伺っているんですけど、その答申を受けて、区のほうでそれを受けとめて具体的に生かすという方向になっていくんですけど、そのときの、でき上がるまでには議会の中で総務委員会等々でも一定の議論する時間というのはあったほうがいいのかなというふうに私は思っているんですけれども。","respondent":"福島長期計画担当課長","answer":"確かに１２月２日に委員会が行われまして、それでこのパブリックコメント等、またこれも含めまして全体についてご意見をいただく予定です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"確認","question":"そうすると、きちんとした長期基本計画というのが答申を受けて、多々意見を受けて、きちんと製本化されて出されるという時期はいつごろなのか、ちょっと確認をしたいと思います。","respondent":"福島長期計画担当課長","answer":"失礼いたしました。２５日に行います。そのときに答申をもらう。答申といいましても、それはあくまでも素案という形でいただきますので、その素案をもとに区のほうがつくると。時期ですけれども、３月中旬を予定しています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"もう一つは、区民の意見というものを、パブリックコメントでは聞いているんだけども、あっ、それはこの間聞いたから、また委員長に言われちゃいそうなんですけど、ちょっと再確認なんですけど、もう一度きちんとこういうふうにでき上がりましたよと紹介をする、周知をするというのかな、そういうのをどういう形でやるのか、ちょっともう一回考えているのを整理の意味で教えていただきたい。","respondent":"福島長期計画担当課長","answer":"こちら、パブリックコメントは今終わったばかりですので、そのパブリックコメントについての結果についてのパブリックコメントを行う予定はございませんし、また答申について、答申の内容についてはパブリックコメントを行っていますので。","voiceIndex":9,"id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"その策定した中身のお知らせというのが、まだどのぐらいの規模で、どういうふうに行われるのかなというのがちょっと知りたかったところなので、ちょっとそこを教えていただきたい。","respondent":"福島長期計画担当課長","answer":"このぐらいの厚みですと、なかなか読んでいただくのも難しいということもありますので、少し縮小したもの、概要版をお配りしまして、区民の皆様にお示ししていきたいなというふうに考えてあります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"土井委員","kind":"意見","question":"ホームページ、ただそのほかの２、３、４番の方々は、もとのあれはどこで仕入れられたかちょっとはっきりわかりませんけれども、でもやっぱり、広報紙は相当強い影響を持っているなという感じがありますよね。ということは、これからまた周知を図るときとかも含めて、ここが一つわかりやすくきちんと書かれているということが大事なんだなという感じがするんですよ。それだけお伝えをしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-005"},{"speaker":"金野委員","kind":"質問・要望","question":"参考までにお声を聞かせていただきたいんですが、あくまでもこの意見内容の数字から見ると、「みんなで築く健康都市・福祉都市」とか、また、「暮らしを守る安全・安心」というところにやはり関心が高いのかな、意見が多いのかな。そこら辺のところで、参考までにどんなお声があったのか、意見があったのか、お聞かせ願えますでしょうか。","respondent":"福島長期計画担当課長","answer":"実は、内容につきましては、まず分析が途中でございまして、正確に申し上げることは大変難しい。すごく内容も多岐にわたってございまして、ここで選びますと、すごく恣意的になってしまうと思いますが、あくまでも今ちょっと見た感じでのご意見という形です。","voiceIndex":14,"id":"exchange-006"},{"speaker":"林委員","kind":"質問","question":"こういうことを言うと怒られるかもわからないけども、これができるわけですわな、３月に。できた瞬間から、これは過去のものになる。その人たちはどのぐらいまで知っているんですか、これ。あくまでも委員会の中だけで文字をいろいろ見たり、それからパブリックコメントをもらった者、かなりの人はしっかりと分析したり見ているんだけど、入っていない課長というのはどこまで見ているんですか、これ。","respondent":"福島長期計画担当課長","answer":"その事務局にも委員会に出ないという課長もいらっしゃいますけれども、この中身につきましては、全課長すべて中身を見ていますし、また内容の確認もしております。このパブリックコメントにつきましても、すべての課長に見ていただきまして内容確認等を行って進めているものです。","voiceIndex":16,"id":"exchange-007"},{"speaker":"林委員","kind":"質問","question":"じゃあ、全員このパブリックコメントに目は通しているわけですね、ここにいらっしゃる課長たちは。そうしたら、そのパブリックコメントを参考にしながら次のステップに入っていく、長期計画は。区議会事務局かな。それが３月までにこの計画ができ上がると同時ぐらいに実施計画というのができてきて、各課の目標というか、毎日の仕事になっていくんだろうと思う。各課でそれをつくっているんですか。","respondent":"福島長期計画担当課長","answer":"ただ、実施計画だけですべて品川区の区政が動いているわけではございませんで、実施計画に載らない事業等もたくさんあります。そういった意味では、実施計画に載らない所管というのもあろうかと思います。","voiceIndex":18,"id":"exchange-008"},{"speaker":"林委員","kind":"質問","question":"だから、載らないものは通常的な日常業務であって、新しく計画をつくって実施計画もつくろうということであれば、品川区として新しい施策の実践というのは、これに基づいて実施されるものが主なものというふうにとる。それで、予算の中で、これは通常の業務、それからこっちは投資的業務と分けて表現する場合もある。実施計画をやっている中で、各課が横串を刺そうとしている事業は何ですか。","respondent":"福島長期計画担当課長","answer":"実際具体的に区政を進めていく、あるいは組織的に進めていく中では、会議体としまして事業部経営会議ですとか、あるいは課題ごとのプロジェクト、検討会を開いたりですとか、あるいは部長会を開いたりですとか、そういうさまざまな会議体を持ちまして。","voiceIndex":20,"id":"exchange-009"},{"speaker":"林委員","kind":"意見","question":"それは踏襲していってほしいし、この新しい計画、長期計画を実現していく実施計画の中で、さらにその横串というのが非常に重要なポイントを持ってくる。だから、総務委員会に限らず、各委員会に出てくる課長たちが横串というのに意識を強く持っておいてほしいと思うので、それは今のリーダーである企画課のところで言っていってほしい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-010"}]},{"id":"topic-02","title":"２番目の大井競馬の昼間開催から夜間開催への変更","agenda":"２番目の大井競馬の昼間開催から夜間開催への変更","exchanges":[{"speaker":"南委員","kind":"質問","question":"それで、特に八潮は競馬場の周辺のところは、一部の地域なんですけど、特に南大井二丁目は競馬場に面してというか、結構大きなマンションが、居住者がすごくいらっしゃいますので、もろに音とか光とか、ごみやほこりなんかもすごいとよく聞くんですけど、そういう状況もあるので、冬場ですから閉め切ってはいるんですけども。","respondent":"伊勢総務課長","answer":"通年でこの時期にやっているかどうかですけども、大井競馬の日程は、競馬組合だけで決められるものじゃなくて、南関東に４カ所ありますので、それが年によって川崎になったり、船橋になったり、浦和になったりしますから。","voiceIndex":28,"id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"南大井二丁目のところに住んでいる方は、わんわんとほこりが上空に舞っていて、風向きではもろに入ってくるという状況ですから、やっぱり心配されるというのはそのとおりだなというふうに思うんですね。その点について多分期待のような答弁はないと思いますので、意見としてしっかり申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-012"},{"speaker":"林委員","kind":"意見","question":"日程というのは、前に決まっているんですよ。急に２５日にやるという話じゃない。１年前からその日はやることになっている。ただ、この日をトゥインクルにするというのは、今日の報告であって、この日を今日突然増やしたという、そういうものではないと僕は思うね。急にここに来て、１２月２５日に開くことになりましたというのは誤解なんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-013"},{"speaker":"林委員","kind":"意見","question":"だから、１年前にあなたの耳には入っているわけ。なぜかというと、大晦日というのは、お客さんが入る。それも毎年年間のスケジュールを決めるときに決まってくる問題で、そのときに地元に説明してくださいよという話ならわかるけど、この場面で急に説明してくださいよといったって、１年前に決まっている話だから、おかしな問題だけど、その辺はちゃんと説明してほしい。","respondent":"伊勢総務課長","answer":"日程は既に１年前に、ほぼ１年ぐらい前から南関東の４カ所できちんと決めて、１２月３１日まで決まっております。そういう面で、１２月２５日につきましては、決まった日程の中でプチトゥインクルから通常の夜間開催になったです。","voiceIndex":36,"id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"ちょっと今のに関連してなんですけども、１年前に決まっているということではあっても、それを議会で私たちが知るのは、私は申しわけない、知りませんでした、今の報告があるまでね。それで、議会に報告しているということだから、じゃあ大分前に報告としてはあったと。しかし、住民の方にとってみれば、いつの時点で知るんですか。ちょっとその辺を知りたいと思っているんですけど。","respondent":"伊勢総務課長","answer":"それから７月３１日にご視察いただいたときに、たしか皆さんにも資料をお渡ししたと思うんですけど、そういうところに１２月までの日程が載っているものです。正確に言うと３月までですけども。３月までの日程が載っているものがあります。","voiceIndex":38,"id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"要するに、そういうところに自分から自発的に行って、その情報を手に入れるというふうにしなければ、入らないわけでしょう、住んでいる人は。だけど、一定の先のことだって、わかっていれば入りますよね、情報公開の時代ですから、当然です。そういう方々が、競馬場に行って、そういうカレンダーをもらわない限り知り得ないという、そういう状況というのは一般的にあるんじゃないですか。","respondent":"須藤委員長、伊勢総務課長","answer":"総務課長、ちゃんと説明していただかないとなかなか難しいので、はっきりお話ししてください。基本的には日程が決まった段階で、競馬組合のほうから地元にこういう日程になりましたということで説明をしているですので、そこから後、町会の中できちんと連絡していただいて、お伝えしていくというふうに思ってあります。","voiceIndex":40,"id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"やっぱり知り得ない人というのはいますよ、どんなことをやってもね。ですから、徹底しろとか、一人ひとり個別訪問して知らせろとか、そういうことは言っていないですよ、そんな常識的でないようなことは言っていないけども、でも一般的にやっぱり知らない人のほうが多いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-017"},{"speaker":"土井委員","kind":"意見","question":"この開催、この日に開催をすることは１年近くも前に決まっていて、それが淡々と今行われてきたんだけれども、これはたまたまＬ－ＷＩＮＧの開設５周年というのもあるから、そういう行事とあわせて夜開催にして、夜のイルミネーションも含めて楽しんでいただこうと、こういう企画ですよということはわかりました。もし、区の職員だったら、夜この時間がずれるときにどうします。馬だけじゃないですよ。","respondent":"伊勢総務課長","answer":"確かに勤務時間等が変わってくるということがありますので、その辺は組合とそれから厩舎の関係あるいは調教師と厩務員の関係、そういう中で整理をされてこういう開催に至ると。具体的にはちょっと聞いておりませんけれども、そういうふうになっているというふうに思います。","voiceIndex":44,"id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"もし、聞き漏らしていたらあれなんですが、今回昼間開催が夜間に変更ということなんですが、競走馬にとっては寒いとまた雨とか雪に対して、特に夜間にやって寒い中で雨とか雪、そういう天候の問題が出てくると思うんですが、競走馬にとっては非常に危険性が高いと思うんですね。故障しやすい。その中で、あえて今回夜間開催するというその理由ですか、それはどのような理由なんでしょうか。","respondent":"伊勢総務課長","answer":"危険性を生むということで、確かに夏場はあったかい日にトゥインクルレースをやっていますけど、寒い時期にやるということで、この辺企画上の問題だとか、その辺はあるのかもわかりませんけども、その辺は獣医だとか、その辺の意見を十分聞いて。","voiceIndex":46,"id":"exchange-019"}]},{"id":"topic-03","title":"３番目の東大井児童センター耐震改修その他工事請負契約","agenda":"３番目の東大井児童センター耐震改修その他工事請負契約","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"これは耐震補強工事ということと、保育園の内部改修なんですけれども、施設そのものは開館したまま続けるのかどうかというのを一つ教えていただきたいと思います。","respondent":"宍戸施設担当課長","answer":"児童課発注の工事ではありますけれども、基本的には居ながらの工事というふうに聞いております。","voiceIndex":53,"id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"保育園部分も当然そういうことでいいのかなと思うんですけれども、来年の３月１９日までだから、当然冬休みも児童センターの部分では期間があるので、子どもたちの利用がいつになく、朝から、午前中からという状況もあるので、児童センター部分がある、保育園のほうも、保育園のほうは内部改修ということと厨房改修なので、ちょっとこの工事の内容があまり平面図を見てこなかったのであれなんですけども。","respondent":"宍戸施設担当課長","answer":"その辺は支障が出ないように工期を十分とっているですし、保育上支障がないように、あるいは生活に支障がないようにそれぞれ工夫しながら行うというふうに聞いております。","voiceIndex":55,"id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"そういうことで、部分部分を区切って工事されるというのは、小さい子どもが居ながらのところだから当然だというふうに思うんですけれども、本当に職員の方々の心労、それからお母さんたちの不安というのは当然あると思うので、改めて対策はとっていただいているということは十分承知しておりますけれども、事故だけは起こさないようにしていただきたいということを申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-022"},{"speaker":"金野委員","kind":"質問","question":"３階、４階のトイレの改修で、ここは図面で見ると、乳幼児対応のトイレというか、子どもを座らせておく場所というような、これはついているんでしょうか。それをまず１点教えてください。","respondent":"宍戸施設担当課長","answer":"この図面が改修前のちょっとトイレの状況になっておりまして、例えば４階ですと男女を入れ替えたような形になりまして、左側にベビーシートがつきます。","voiceIndex":58,"id":"exchange-023"},{"speaker":"金野委員","kind":"意見","question":"２点目に、トイレの対応はしてくださっているということで、１階の保育室のほうで、鉄骨ブレース設置、これは多分外側に出る側のドアのところなのかなと思うんですが、こういった工事のときにも安全は当然期していただくと思うんですが、その点は大丈夫なんですよね。","respondent":"宍戸施設担当課長","answer":"例えばここの１階の部分の工事をしているときには、１階は一応お子さん方は使わないようにきちっと区画をして、２階で生活をしていただくなど、工事をしている場所については使わずにやるというふうに工夫をしながら工事を進めるというふうに聞いております。","voiceIndex":60,"id":"exchange-024"},{"speaker":"金野委員","kind":"意見","question":"そうすると、工事というのは１日、２日のことじゃないですよね、それなりの時間で。要するに２階に、区画で行くといっても、０歳、１歳、２歳のお子さんがいて、幼児となるとかなり動きが活発になってくるというのを考えると、単純に移動しただけで大丈夫なのかなと思うんですが、どうでしょう。","respondent":"宍戸施設担当課長","answer":"それで、今回この工期が３月ですので、通常学校ですと夏休み期間中で耐震改修工事を終わらせますが、そういう意味では、規模が小さいにもかかわらず、これから４カ月ぐらい使ってこの規模の工事をするということで、通常の２倍以上の工期を使いながら。","voiceIndex":62,"id":"exchange-025"},{"speaker":"金野委員","kind":"質問・要望","question":"ぜひこの幼児と乳児との動きが全然違うところで、今までもそうだったという流れもあって、今までやってきた中での、またここで安全を期した今までのいわゆる経験を踏まえて、区画整理をしながらお子さんを安全にしていくんだろうと考えてくださっているだろうと思うんですが、より万全を期していただくために多分お昼寝の時間、それから食事の時間。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-026"},{"speaker":"林委員","kind":"意見","question":"２ページの入札のあれなんですけど、５社がいて、２社が辞退。２社とも品川の会社なんですね。ほかの３社、参加した３社は品川の会社じゃない。何と言えばいいのかな、本体は品川じゃないという言い方がいいのかな。それで、ちなみに僕、ちょっと数字の計算、頭があれなんで、何パーセンになりますか。","respondent":"阿部経理課長","answer":"落札率は９９％です。","voiceIndex":65,"id":"exchange-027"},{"speaker":"林委員","kind":"意見","question":"辞退した理由まではわからないんでしょうけども、９９％で落ちるという工事をこういうふうに辞退するというのはなぜなんでしょうね。これが例えば昨日の５０％を切るとか切らないとかという数字だったらわかる。これだけの数字を辞退するというのは、行政として何か理由がわかりますか。","respondent":"阿部経理課長","answer":"その段階で参加する企業は参加しますという形にいたします。その後に会社として積算をしていきます。その積算の結果が予定価格を上回ったのではないか、そういうところが考えられるのかなと考えています。","voiceIndex":67,"id":"exchange-028"},{"speaker":"林委員","kind":"質問","question":"この耐震ということが絡んできて、１億４,０００万円に約６,０００万円、約２億かかると。耐震工事としてはかかってくるんだということで、ちなみに児童センター、これから耐震工事、こういうような工事は幾つぐらいあるんですか。","respondent":"宍戸施設担当課長","answer":"平成２０年度に９件、９施設発注する予定です。工事の進み方としては、夏休み工事が終わって後半の時期ということなので大体重なると思いますけれども、９件、９施設。","voiceIndex":71,"id":"exchange-029"},{"speaker":"林委員","kind":"質問","question":"ほぼ今年度で耐震に関しては完了というふうに認識しておいてよろしいわけですね。戻ります。通常の流れでこういうふうに来た。価格の変動もやりますよというふうに言っているから、業者のほうも幾らか助かるというか、変動に備えられるということになるわけですけど、工事に支障を与えるほど辞退をされるということはないですか。ないだろうというふうに読んでいますか。","respondent":"阿部経理課長","answer":"先ほど申し上げたような理由で辞退はあるとは思いますけれども、今のところはこの大型物件について不調ということはございませんので、今後順調と言っていいのかどうかわかりませんけれども、私どもとしては。","voiceIndex":75,"id":"exchange-030"},{"speaker":"林委員","kind":"質問","question":"応札がない事態が進んじゃって、工事ができないということは、行政としても施策がおくれるということになるわけですから、十分な下準備というか、資材その他、準備、計算は整えて発注、入札をしてほしいと思うんだけど、それはお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-031"},{"speaker":"須貝委員","kind":"質問","question":"意見と質問なんですが、意見は先ほどの児童センター、保育園を運営しながら耐震改修をやるということですが、くれぐれも注意をしてほしい。やはり、同じ階で、まして鉄板巻補強となると、中に資材を運ぶわけですから、ちょっと触れただけでも大変な大けがをすると思いますので、よろしくお願いいたします。それだけちょっとお聞かせください。","respondent":"宍戸施設担当課長","answer":"ただ、その辺の値下がりの動きというのに準じて標準単価のほうを、このところ、約１カ月ごとに東京都のほうから出されておりまして、我々のほうもそれに準じた形でなるべく速やかに対応するようにしておりますので。","voiceIndex":78,"id":"exchange-032"}]},{"id":"topic-04","title":"の補助３２０号線（武蔵小山駅前広場含む）整備工事請負契約","agenda":"の補助３２０号線（武蔵小山駅前広場含む）整備工事請負契約","exchanges":[{"speaker":"林委員","kind":"質問","question":"１３ページの初歩的な話を先に聞きますけど、東急の持ち物というのは、この絵の中でどこが東急の持ち物で、３２０号線というのは、書いてある歩道の話になるんだろうけども、これはだれの持ち物というような話はしないんですか、こういうときは。でも、あるんでしょう。東急の土地、ここは品川区の土地、これは東京都の土地というような、そういうことは電車の場合はやらないのか。","respondent":"阿部経理課長","answer":"今回はあくまでも整備工事の内容ですので、そういう説明をいたしました。この図で、じゃあ東急のところはどこかと申しますと、当然この線路を走っていますけれども、ここに白い地図があります。","voiceIndex":85,"id":"exchange-033"},{"speaker":"林委員","kind":"質問","question":"それで、そこをどうしても武蔵小山の出張所というか、不便だと、駅から、出入口から離れて。あそこの整備が終わったら便利になるよという話をしちゃったんだよね、僕ね。そうすると、出入口というのは左の下でしょう、階段みたいなのがあって、エスカレーターの絵がかいてあって。そうすると、あそこの場所は移さないんですか、品川区のものは。駅の近くに。","respondent":"阿部経理課長","answer":"私、移すというふうには聞いてはおりませんので、移す予定はないんではないかと思います。","voiceIndex":87,"id":"exchange-034"},{"speaker":"林委員","kind":"意見","question":"移さないね。じゃあ、もう一つ次に、バス停が中に入ってくる。バスの停留所が中にあって、バスが入ってくるという絵になっているんだけど、このバスはどこから武蔵小山までなのか、あるいは武蔵小山は途中の駅で、大井町まで続くのか、その辺をちょっと聞かせてください。","respondent":"阿部経理課長","answer":"それがここに入ってくるんだろうと思います。もう一点は、私が前任だったときに、東急のほうと２６号線が全面開通したときには、武蔵小山方面から大井町方面にバス路線を新設するということで東急とは話し合いをしております。","voiceIndex":89,"id":"exchange-035"},{"speaker":"林委員","kind":"質問","question":"後者の部分はまだちょっと先の話だけど、これは半年先にはここにバスが入ってくる。そうすると、そのバスは目黒通りから入ってくるんですよね、今の話になると。中原街道からは、あそこの出入口を工事しているから、バスの出入りがしやすくなるかもわからない。このバスは、じゃあ目黒通り、目黒郵便局のほうからここに入ってくるバスになるわけですか。","respondent":"阿部経理課長","answer":"両方だと思います。要するに、五反田から来るバスもありますので、それも入って、五反田とたしか世田谷区民会館、忘れましたけども、それを結んでいるバス路線、従来からあるバス路線はこちらに入ってくるんだと思います。","voiceIndex":91,"id":"exchange-036"},{"speaker":"林委員","kind":"質問","question":"あっ、そうですか。武蔵小山全体の開発とも見合せながら、こういう駅前広場の整備をしていくということになるわけで、そのほかの整備、区画が何カ所かに分かれているから、人の、あるいは車のこういう出入りが非常に読みにくい場所というふうに考えるんだけど、武蔵小山全体にとっては、この話は歓迎されていますか、それとももっとここ、あそこという話になるわけですか、そこまで話は進んでいない。","respondent":"日下部企画財政課長","answer":"私どものほうで承知している限りでは、やはり駅前広場がしっかり整備をされますし、そういう意味では商店街への人の流れも比較的スムーズにこれから行くことになるだろうという意味で、かなりあの地域のほうとしても歓迎をされているということで承知をしています。","voiceIndex":93,"id":"exchange-037"}]},{"id":"topic-05","title":"５番目の補助１８号線電線共同溝整備工事請負契約","agenda":"５番目の補助１８号線電線共同溝整備工事請負契約","exchanges":[{"speaker":"土井委員","kind":"意見","question":"１７ページの絵を見ますと、工事施工箇所の黒く塗ってあるところ、区境を挟んでいるんですけれども、ここら辺はどうなっているのか説明していただけませんか。","respondent":"阿部経理課長","answer":"今回は品川区の工事ですので、１８号線は品川と目黒を結んでいまして、目黒側は既に整備を終了しています。","voiceIndex":100,"id":"exchange-038"},{"speaker":"土井委員","kind":"質問","question":"ということは、目黒のほうは工事が済んだよと、それの続きとして我がほうが工事をするよということで、これで目黒通りまで、目黒通りじゃないな、これは何通りだ、あそこまでつながるということなんですね。わかりました。あれっ、境目は何色になっているのかなと思いながら見ていたものですから、わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-039"},{"speaker":"須貝委員","kind":"質問","question":"今回入札した会社が２社ということなんですが、この工事は特殊なんでしょうか、それとも品川区内と限定すると、やはり２社しか該当するところがなかったんでしょうか。それとも辞退、辞退というか、もともと入札しなかったのか、その辺をわかる範囲でお聞かせください。","respondent":"阿部経理課長","answer":"２社しかないということではございませんで、前回ご報告いたしましたように、北品川、旧東海道部分も電線共同溝をしておりますので、そういう関係もございまして、今回は２社の応募があったということだろうというふうに考えております。","voiceIndex":105,"id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1804#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":24502,"voices":114}},{"id":"h20-20081127-14","meetingId":"h20-cm11","date":"2008年11月27日","dateIso":"2008-11-27","committee":"行財政改革特別委員会","time":"午前１０時０２分～午後０時２０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"請願・陳情審査とも関連・重複する部分もございますので、理事者の説明につきましては、特定事件調査と請願・陳情審査","agenda":"請願・陳情審査とも関連・重複する部分もございますので、理事者の説明につきましては、特定事件調査と請願・陳情審査","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"両案とも区民の利用に供していくという点では私も評価をするところですけれども、いただいた資料の中で、この案を出すに至った経過というのがちょっとよくわからないものですから、この両案について時系列的に、この案を出すに至ったまでの経過について、ちょっとお聞かせを願いたいと思います。","respondent":"久保田行財政改革担当課長","answer":"そうした経過の中で、やはり文書だけではなかなかイメージがつかめないといったご意見もいただきましたので、設計図というか図面という形ではないですけれども、そんなような具体的なイメージがわくようなものはないかといったご意見もございましたので。","voiceIndex":5,"id":"exchange-001"},{"speaker":"菊地委員","kind":"質問・要望","question":"今、前の委員会のときにというお話がありましたけれども、今、私がお聞きしたのは、学校跡地ができますよということが確定をした時点から、今、地域の皆さんの意見もお聞きしたというお話だったんだけれども、要はその確定をしたときからどういうふうにこれらを策定をしてきたのかということをお聞きしているので、例えばいただいた資料の２ページに利用計画案とありますけれども。","respondent":"久保田行財政改革担当課長","answer":"そうした中で、こちらの資料にも書いてありますけれども、荏原地区というものは従前より防災性の向上が急がれる地区だという認識を持ってありますので、そういったものも一定程度担保しつつ整備をしていく必要があるだろうというところで、検討を進めてまいりました。","voiceIndex":7,"id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"１０月２日のときの当委員会で説明をしてくださった中身と、資料そのものも新たに図面がついたというぐらいで、別に大きな変わりはないわけなんですけれども、今、お聞きした中で、これは今回のは２つの跡地ですよね。荏原地区だけのことではなくて、何を基準にしてこういう跡地利用を考えていくのかというところをもう少し教えていただけますか。","respondent":"久保田行財政改革担当課長","answer":"今回、一貫校になりまして、この２校の跡地利用といったところでも、例えばスポーツ団体の活動ができる施設が少なくなってしまうというような現状も想定されますところから、この両校、平塚小学校と荏原平塚中学校は同じエリア内にありますので。","voiceIndex":9,"id":"exchange-003"},{"speaker":"菊地委員","kind":"意見","question":"今、スポーツ施設のお話をしてくださいましたけれども、例えば平塚小学校ですと、ここは文化施設をつくりますと。舞台やホールをつけた文化施設をつくるというんですけれども、この地域で見れば、例えば荏原文化センターからこの小学校跡地はかなり近いところにありますよね。こういうところの考え方、そういうところをどういうふうに考えるのかというのもお聞かせ願えますか。","respondent":"久保田行財政改革担当課長","answer":"そうした中では、例えばホール等を使って地域の方が今まで学んできたような、例えば音楽とか演劇みたいなものの発表といったところも必要なのではないかなというところで考えておりまして、近くにはありますけれども。","voiceIndex":11,"id":"exchange-004"},{"speaker":"菊地委員","kind":"質問・要望","question":"区内全体を見たときに、１つの基準を置いて、じゃあ、跡地をどういうふうに活用していくかという見方ができるんだと思うんです。１つのルールを明確にして、その上でその地域の特性も考えて何が必要か。こういう考え方をやはり示していただきたいんです。ですからその辺をちょっともう少し明確に示していただきたいと思うんですけれども、ちょっと最後にそこだけお聞かせ願います。","respondent":"久保田行財政改革担当課長","answer":"基本的なルールというご質問ですけれども、基本的な跡地活用に対する考え方につきましては、これまでさまざま議会等でもご説明・ご答弁をさせてきていただいておりますけれども、私どもにとりましてはこういった土地は非常に区民の貴重な財産であるというところから。","voiceIndex":13,"id":"exchange-005"},{"speaker":"菊地委員","kind":"質問・要望","question":"そういう一つ一つの問題点を見ながら、具体的にだれもがわかるような示し方というのが必要なのではないかと思うんです。やはり今、区民が求めている、そうした高齢化が進む中で高齢者の施設はどうなんだとか、そういう考え方をやはり基本に置くべきだと私は申し上げているんですけれども、その辺の具体性のところで、ちょっと最後にします。もう一度だけちょっとお願いします。","respondent":"久保田行財政改革担当課長","answer":"そうした中で、全体的な行政需要といったものはどれかといったところで計画化しておりまして、区民の皆様にお示しをしているといった中です。そうした中で検討を進めているといったところです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"阿部委員","kind":"質問","question":"幾つかお伺いしたいのが、まず駐車スペースといいますか、このイメージ図の中からどの程度読み取っていいかちょっとわからなかったものですから、大体ということでお伺いします。駐車スペースというのが載っていますが、これ駐車スペースというのは基本的に地上面にこんな感じであるということなんでしょうか。それを教えてください。その可能性について、教えてください。","respondent":"久保田行財政改革担当課長","answer":"荏原平塚中学校のほうの民家の方への対応ということで、まず１点目、土と砂ぼこり対策ですけれども、こちらはまちづくり事業部のほうに確認しましたらば、例えば基本的にこちらは土というか多目的広場なので。","voiceIndex":17,"id":"exchange-007"},{"speaker":"阿部委員","kind":"質問","question":"さっき聞いた中で、公開空地・前広場の現状での具体的なイメージといいますか、そこをもう一度教えてください。そのハード面でもう少しこのイメージよりも増やしていくことも含めて、今の段階で教育委員会と協議されるということなのかどうか、そこを教えてください。","respondent":"久保田行財政改革担当課長","answer":"公開空地の利用ですけれども、あくまでも現時点でのイメージというところでご理解をいただきたいんですけれども、荏原平塚中学校とこちらを一体的に整備するというご説明をさせていただいた中で、向こう側。","voiceIndex":19,"id":"exchange-008"},{"speaker":"阿部委員","kind":"質問","question":"設計段階から考えていただけるということで、ぜひ将来的にも後悔しないような形で検討していただけると思います。地下とかを使えば随分、あのエリア全体の駐車場利用にかなり貢献できるような、素人考えですけれどもいかがでしょうか。","respondent":"久保田行財政改革担当課長","answer":"地下駐車場のご質問ですけれども、地下駐車場というものもいろいろと検討してきたところはあるんですけれども、地下駐車場にかかる経費というものが地上用に比べてかなり経費がかかるといったところもありますので。","voiceIndex":21,"id":"exchange-009"},{"speaker":"阿部委員","kind":"意見","question":"駐車場に関しては、経費は当然たくさんかかると思うんですけれども、安全性とか動線のこと、それから美観、まちの景観としての価値、そういったことも含めて再度検討していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-010"},{"speaker":"須藤委員","kind":"質問","question":"何点かダブるかもしれません。球技とかその程度かなと。それから前広場についても、今、質問があったように、空地が必要だ云々だというのでやってくる。やはり全体的に、前は体育館があってどうのというような話だけれども、それをなくしました。それから今、駐車場についてもここで何台ですかと、何台ぐらいとめられるのか。喫というのはどういう意味なのか、教えていただければと思います。","respondent":"久保田行財政改革担当課長","answer":"たばこは、それはまた具体的にできましたら、どういう運用になるかはその中でいろいろ検討する必要があるのかなとは考えておりますけれども、お茶を飲むという意味で、お茶を喫するというような意味で、よろしくお願いいたします。","voiceIndex":24,"id":"exchange-011"},{"speaker":"須藤委員","kind":"質問・要望","question":"舞台・ホールのほうがどのくらいの定員かというのはちょっと教えてもらえなかった。どのくらいの広さか。幼保一体化が必要なんだというのだったら、もう半分ぐらい幼保一体化でどうのというぐらいのことができないのかなとか、何かこうちまちますると、ちょっと小さいというのも出てきてしまうような気がするので、そのあたりの考え方を教えてもらいたいと思います。","respondent":"久保田行財政改革担当課長","answer":"ホールの定員ですけれども、具体的に何人というのはまだちょっとこの段階では決まってはいないところなんですけれども、ただきゅりあんで、今、１,０００人ぐらい入っていますけれども、そういう規模では難しいのかなというふうには考えているところです。","voiceIndex":26,"id":"exchange-012"},{"speaker":"井上委員","kind":"質問・要望","question":"これだけを見たとすると、この駐車スペースというのは、ここの利用者のスペースではないかというふうに普通に考えれば思うと思うんですけれども、そこら辺の、この3)の明記を外して、こういった計画になったところ、前のときには「一定規模以上の」ということがあったんですが、今回のところでは抜けていますので、そういった表記の違いがどういう意味なのか。","respondent":"久保田行財政改革担当課長","answer":"それで、場所としましては都市計画公園、この緑色の都市計画公園の左隣のところに体育館があるといったところでございまして、まず１点目といたしましては、できれば経費の面で体育館の活用をしながら、スポーツの利用に供していただければと考えておりましたけれども。","voiceIndex":28,"id":"exchange-013"},{"speaker":"井上委員","kind":"質問・要望","question":"細かいところでは、体育館もスポーツ室と書かれると非常に何か小さいものをイメージしてしまうのですが、現行の体育館の球技ができるような、そういった舞台を除いたスペースなのか、その辺のスペースの考え方をお伺いしたいことと、あとここの都市公園と先ほどの公開空地のところなんですけれども、今、新基本構想の子どもたちによる記念公園の計画がされていて。","respondent":"久保田行財政改革担当課長","answer":"ただ、こうした中で広さの問題とかもあるんでしょうけれども、公開空地とかいったところで、公開空地の防災機能も持たせながらの整備というところになりますと、なかなか記念公園として考えていくところは難しいのではないかというところでございまして。","voiceIndex":30,"id":"exchange-014"},{"speaker":"井上委員","kind":"質問","question":"この前広場・公開空地というのは、防災広場としての位置づけがあるということですか。","respondent":"久保田行財政改革担当課長","answer":"防災広場としての位置づけがあるというところではございませんので、学校の敷地としてはありますから、そういった制約というものは特にございませんけれども、例えばそういう防災機能を残してもらいたいという声もありますし。","voiceIndex":32,"id":"exchange-015"},{"speaker":"浅野委員","kind":"質問・要望","question":"私のほうからも何点か、質問します。それと都市公園との連続性ですけれども、こちらも今の景色というんでしょうか、補助２６号線、平塚橋の交差点を進んでいったところから随分変わっていくんだなという期待をこめて、ここの一体的な整備をぜひ望みたいなと思います。そしてまた太い道路がありますけれども、住宅地にあるというところ、ここら辺もしっかり配慮していっていただきたい。全部言ってしまいます。","respondent":"久保田行財政改革担当課長","answer":"駐車場の地下化というものも検討してもらいたいというご質問ですけれども、先ほど来申し上げましたけれども、地下という駐車スペースを考えていく中では、費用の問題といったものもあります。","voiceIndex":34,"id":"exchange-016"},{"speaker":"渡辺委員","kind":"質問・要望","question":"週１回程度の適度な活動をするのもおぼつかないぐらい、１７地区それぞれが大変な申し込み状況がある、利用者が多い中では、１面つくるのであれば、こういったチャンスを逃さず、やはり面数ですとかスペースの拡大というのは、先ほどの武道場の話もありましたが、このチャンスを逃したらもったいないのかなという気がしますので、そういったつくり方の点でもう一度伺えればと思います。","respondent":"久保田行財政改革担当課長","answer":"１点目、屋根のところの有効利用ですけれども、屋根というところでちょっと丸くなっている、イメージとしてつくっていますので、丸いといったところもありますが、今、フットサル場といったようなご提案もありましたけれども。","voiceIndex":37,"id":"exchange-017"},{"speaker":"渡辺委員","kind":"提案","question":"今の最後のスポーツ室は、社会人や子どもという区分けというよりは、コートの面の数という点でご要望したいなと思いました。多目的ホールのこともそうなんですが、構想をどうこうという発想ではなくて、４階があと１階増えることで、施設の例えば部屋数が仮にそこに３部屋あるとしたら、１階増えることで６部屋あると、こういう程度の要望です。","respondent":"久保田行財政改革担当課長","answer":"例えばぎりぎりまで敷地というわけではなくて、例えばちょっとした緩衝帯みたいなものを設けて少しでも見た感じでもそういう家のほうに張り出してこないような、そういうイメージでの、イメージ上での防音みたいなという手法もありますので。","voiceIndex":39,"id":"exchange-018"},{"speaker":"安藤委員","kind":"提案","question":"意見の表明または提案の機会を保証していく。これは何度も要望しているところなんですけれども、やはり区の意見の計画案をまず知らせていくことで、そのことで初めて意見というのは出ると思うので、そういった意味でもこの区として説明会というのを地域で開く考えはあるのかということを、３点になりますか、お伺いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"地域に対しましてはこれまでいろいろ意見を伺ってまいりましたけれども、そういった意味で連合町会とかから意見交換はしてきましたけれども、改めてこれについて説明会を行うといった予定は考えてございません。","voiceIndex":41,"id":"exchange-019"},{"speaker":"安藤委員","kind":"提案","question":"ですから、私は説明会というのは、このパブコメの期間中にやるか、あるいはパブコメが終わった後、意見を伺った上でさらに説明会をやるのか、それはどちらがいいのかわかりませんけれども、少なくとも今回のこういう学校跡地をどうにかするというところの機会であれば、これを機会にやるべきなのではないかと考えていますが、私は強くそういうように思っているんですが、再度。","respondent":"久保田行財政改革担当課長","answer":"ただ、そうした中で、このパブリックコメントをやるに当たって、説明会をやるかといったところでは、現時点ではパブリックコメントによる説明会よりも、パブリックコメントをやって広くホームページとか広報紙で意見を聞くことによるほうが効果があるというところで。","voiceIndex":43,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"説明会を開くことによって、例えば今まで接触できなかったような方々の意見も聴取できるかもしれないし、あるいはほかにもいろいろとあると思うんです。そういう仕組みをつくっていく必要があるのではないかというふうに思うんですけれども、そこについてもご意見を伺いたいと思います。","respondent":"久保田行財政改革担当課長","answer":"そういった意味では、今回の跡地利用計画案については協議会をつくって、そうしたような形での進め方はとってはいないというところでございまして、そういう仕組みをつくって一律的にやるのがいいのかどうかというよりも。","voiceIndex":45,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり私はありとあらゆる手段をとって、住民の意見を伺う機会を持つということがとても大切だと思うんですけれども、１度もこういう跡地活用でこれまで住民に直接ご意見を伺うような説明会というのは、これまでも行われてきませんでしたし、そういったことを１度もやっていない中で、これをまず１度やってみて、この対面の説明会による意見聴取のやり方ということに対する経験というんですか。","respondent":"久保田行財政改革担当課長","answer":"説明会に対するメリット、デメリットということのお話でございましたけれども、私どもはできるだけ多くの方からの意見をとりたいといったところがありますので、そうした意味では、あとそれに対しまして効率的に広くたくさんの方の意見をとりたいという思いがありますので。","voiceIndex":47,"id":"exchange-022"},{"speaker":"金野委員","kind":"質問・要望","question":"それから２点目に、幼保一体施設がここでつくられていくということなんですが、ここに期待されている定員が１００名から１５０名程度ということになりますと、この間視察をさせていただいて、園庭の広さ、それから園舎の中を見させていただいて、人数が増えるということは当然園庭も、このイメージ図で言うと既存のスペースなんでしょうか。その２点をまずお願いします。","respondent":"久保田行財政改革担当課長","answer":"駐車場の問題ですけれども、現時点では私どもとしましては平面の平場の屋外の駐車場というところで考えておりまして、先ほどもご説明いたしましたけれども、地下というものは非常に経費のかかるといったところもありますので、今の時点では難しいのかなと考えているところです。","voiceIndex":49,"id":"exchange-023"},{"speaker":"金野委員","kind":"質問・要望","question":"予算はやはり皆さんのために使う予算ですので、やはり経費削減、確かに行財政改革としては大事なことなのかもしれないですが、使うべき予算は使っていき、必要なところにはやはり経費をかけていくという考え方でぜひ、まだイメージという段階である、案の段階であるということなので、その考えもどうぞ含めていただきながら、今後、ぜひ考えていただきたいと思います。その点はいかがでしょうか。","respondent":"久保田行財政改革担当課長","answer":"やはり子どもの安全というものは大切なものだと考えておりますので、そういった意味ではスペースが広くなる、どれぐらい広くなるかちょっとあれですけれども、そういった中で検討はしていきたいと考えています。","voiceIndex":51,"id":"exchange-024"},{"speaker":"金野委員","kind":"質問・要望","question":"駐車スペースのほうもよろしくお願いします。子どもの声だけではなくて、ボールの当たる音がという意見もほかのところで聞いたこともありますので、ぜひそういった金網の材質というのでしょうか、そういったところも含めて防音対策にぜひ、これは要望です。よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-025"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"初めに平塚小学校なんですが、学校跡地等の利用についての基本的な考えで、一番初めに防災性の向上というふうに書かれていて、実際にこの利用計画案を見ると３番目に防災対策として、一時的な集合場所としても使える多目的公開空地と書いてあるんですが、ちょっと僕も荏原地区の把握はしていないんですが、例えばほかの地区では町会等の防災に関しての備蓄倉庫とかポンプを置く場所とか。","respondent":"久保田行財政改革担当課長","answer":"は例えば今のところであるのは、特定の町会・自治会というか、防災の資機材倉庫というような形で公園を一部置き場を貸しているといった例はありますけれども、特定の団体に区の施設を貸し出すというところは、そういった意味では難しいのかなと考えております。","voiceIndex":54,"id":"exchange-026"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"それぞれありがとうあります。今、防災対策の特定の町会等にはなかなか貸すことができない。音楽用の防音室はぜひ、若い子たちも使える、また大人、団塊の世代とかも、仕事をやめられて新しくそういった生涯学習の中での活動で、バンドをまた新たに始めたりという人たちも非常に多いというふうに伺っていますので、ぜひともそういった活用ができるような施設にしていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-027"},{"speaker":"高橋委員","kind":"質問","question":"ちょっと何も書いていなかったのでその点と、もう一つは先ほどちょっと防災のことがあったんですが、一時的な集合場所、レベルといってはおかしいですけれども、そこぐらいの防災でお考えなんでしょうか。","respondent":"久保田行財政改革担当課長","answer":"防災のことですけれども、一時的な集合場所というところでご説明しましたけれども、一時的に何かあったときにはここに避難していただいて、それぞれ指定された学校の避難所とかに行っていただくところもありますし。","voiceIndex":57,"id":"exchange-028"},{"speaker":"高橋委員","kind":"質問","question":"１つだけ。ですからそういうことをほかの自治体等の事例などを参考にして、そうなったときのスペースづくりというか、そういうのをやられていただくと、ひいては避難された方々の安全につながるので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-029"},{"speaker":"菊地委員","kind":"質問","question":"１つだけ教えてもらいたいんです。両施設の管理体制は、今、どういうふうに考えているのか、そこだけお聞かせを願います。","respondent":"久保田行財政改革担当課長","answer":"管理体制ですけれども、具体的にこういう管理でというところまではまだ行ってはいませんけれども、まだ利用計画案の段階ですので、これで利用計画が決まりまして、施設の概要が決まった段階で。","voiceIndex":60,"id":"exchange-030"},{"speaker":"菊地委員","kind":"意見","question":"最近の施設の管理というのは、結構、これがどうかということではないですけれども、指定管理者だったり、あるいは業務委託だったり、いろいろな形がありますけれども、その辺での考え方を、これもまだ後の話ですよというのであればそれでいいんですけれども、その辺の考え方をちょっとお聞かせ願います。","respondent":"久保田行財政改革担当課長","answer":"まだ先ほどもご説明いたしましたけれども利用計画の段階ですので、具体的にこちらの建物ができた後、業務委託にするのか指定管理にするのかといったところについては、まだ検討の段階には至っていないです。","voiceIndex":62,"id":"exchange-031"},{"speaker":"井上委員","kind":"確認","question":"先ほど駐車場のところで議論になっていたので、これを検討する大きな柱のために確認をするんですけれども、この駐車場は外部の人たちが有料で使うことを想定しているのかどうかということと、あと１点、経費がかかるということが答弁にありましたけれども、実際問題、この平塚小学校の利用計画の中で、どのぐらいの財源を使って進めようとしているのか、当然今の段階ではあらあらなんですけれども。","respondent":"久保田行財政改革担当課長","answer":"幼稚園の関係ですけれども、幼稚園の関係につきましては、こちらはいろいろと施設を建てていく、工事を進めていく中でも幼稚園というものの運営というものは必要ですので、工事計画の中で、幼稚園のほうの運営を継続しながら、どういった改修工事ができるのかというところも、今。","voiceIndex":64,"id":"exchange-032"},{"speaker":"井上委員","kind":"質問・要望","question":"これだけのこういった方針をつくっているときに、予算規模が何も示されないというのは、そういうものなんですかと逆に問いたいというか、学校１校を建てるにも２５億円ぐらいかかりますよということがある中で、これから予算を立てていく、なおかつ基本計画、設計、実施設計をしていく中で、大体の規模、１００億円かけるんですか、５０億円かけるんですか、２０億円なんですかという。","respondent":"久保田行財政改革担当課長","answer":"予算規模ですけれども、今、いろいろ長期基本計画を策定していく中で、全体の中でこういう規模についてどれぐらいかという検討は進めているところです。","voiceIndex":66,"id":"exchange-033"},{"speaker":"井上委員","kind":"質問・要望","question":"やはりこういった問題は財政ありきで進むしかしようがない部分がありますので、もちろん細かいものでなくて、これは変わったことがどうなんだと責めるつもりはありませんし、こういうところが議会が把握していることで、予算・決算の話とかそういった長期的な展望も見えてくると思いますので、今日は出せないということですけれども、ぜひとも当たり前に情報が公開されるべきことだと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-034"},{"speaker":"安藤委員","kind":"質問","question":"防災の観点でちょっと１つだけ。これまで学校を避難所として指定されていたと思うんですが、小中一貫校になって、小学校の部分とあと旧荏原第二中学校の部分が、そういった点ではなくなるわけですけれども、その今までの避難所に指定していた分の人数というのは、このことによって足りなくなってしまうのではないかなと単純にちょっと思ってしまったんですが、ここら辺はどうなっているのかお伺いします。","respondent":"久保田行財政改革担当課長","answer":"ただ、そういった意味でもまた今後引き続き、防災課のほうで検討していく必要はあるのかなとは考えていますけれども、今の時点ではそういうことです。","voiceIndex":69,"id":"exchange-035"},{"speaker":"原委員","kind":"質問・要望","question":"それから駐車場については、大雑把なところで、皆さん費用のことなんですけれども、最低でも１.５倍から１.７５倍ぐらいは最低かかってくるだろうと思いますけれども、この辺はちょっと新しい、品川区は新しいことが好きなので、建設協力金とか、もう少しいろいろな考え方を持って、広く、ただ費用が出る出ないということだけではなくて、もう少し、せっかく行革なんですから。","respondent":"久保田行財政改革担当課長","answer":"そうした中で、こちら平塚小学校のほうの文化施設につきましては、舞台・ホールというものがありますけれども、五反田文化センターとの違いというところでは、そういった意味では、そこまで和太鼓とかいうところまでどうするかというのも今後の検討ではありますけれども。","voiceIndex":71,"id":"exchange-036"},{"speaker":"原委員","kind":"質問・要望","question":"ところが実際に使われてみたらば、いろいろなほかの目的に使うような形になってしまったものだから、具体的には音が漏れて出てしまったとか、それで実際に設計の五反田のものなんかは非常にいい施設が大分設備的には入ってきているみたいで、専門化できているなという気はするんですけれども、ですからさっきから各委員がお話しされているように、３０年、４０年。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-037"},{"speaker":"阿部委員","kind":"質問・要望","question":"もう時間も押しているので、要望を１つ。というのは、当然公共施設ですから、基本的に禁煙になると思うんですけれども、比較的新しい建物でも、全館禁煙になったものというのは、喫煙者がどうも入り口のわきとか、敷地の周辺とかに固まって喫煙をしている姿を見るというのが、区内の新しい建物の周辺でもよく見られます。よろしく、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-038"}]},{"id":"topic-02","title":"請願第２０号 荏原平塚中学校の跡地をスポーツの出来る多目的広場として整備を願う請願","agenda":"請願第２０号 荏原平塚中学校の跡地をスポーツの出来る多目的広場として整備を願う請願","exchanges":[{"speaker":"須藤委員","kind":"意見","question":"せっかく旧二中のところの跡に、全天候型みたいな、自治体で初めてですということはやる気ないの。どうせやるならそこまでやる気というのは。あれは幾らぐらい。それこそ費用はめちゃめちゃかかるだろうけれども、そんなことは想定したことはあるか。","respondent":"久保田行財政改革担当課長","answer":"すみません。全天候型の施設整備というものは、ドームですよね。ちょっと今回の利用計画案の中では、申しわけございませんけれども検討はしておりません。","voiceIndex":78,"id":"exchange-039"},{"speaker":"浅野委員","kind":"意見","question":"今回のパブコメにも前提としてもありますように、スポーツのできる多目的広場ということで、こちらのほうはやはりしっかりとつくっていくということで、請願のほうは採択という形にしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":91,"id":"exchange-040"},{"speaker":"阿部委員","kind":"意見","question":"本日のこれまでの議論からも、採択ということで全く構わないと思います。たしか請願理由のところではちょっと野球に特化した話がありますけれども、実際には多目的広場ということで、さまざまな種目のスポーツが使えるようなことに当然配慮した整備を行っていければと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5852#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":47586,"voices":102}},{"id":"h20-20081128-16","meetingId":"h20-cm11","date":"2008年11月28日","dateIso":"2008-11-28","committee":"街づくり特別委員会","time":"午前１０時０２分～午前１１時５７分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"八潮のまちづくりに関すること","agenda":"八潮のまちづくりに関すること","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"この資料の２ページのところに、航空法に基づく建築物等の高さ制限を遵守すると書いてあるんですけど、この航空法に基づく高さというのは、何ｍになっているのかを改めて確認したいのと、あと沖合展開をしたことによって、その数字がいつかの時点で変化しているのであれば、ちょっとそれもあわせて教えていただきたいと思います。","respondent":"青木都市開発課長","answer":"４点ご質問があったと思いますが、お答えいたします。説明会の案内を発送した相手方ですけれども、これは地区計画を予定しています約４０.８haの中で、登記簿を調べまして、そこで所有権もしくは抵当権を記載されている方々に発送しています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"それぞれわかりました。それと、緑道の関係なんですけど、緑道１号のところは都営住宅とおっしゃったけど、これ、もとの八潮南中学校と分譲住宅の間の通路と、それから都営住宅との境の通路というふうに思うんですけど、位置が知りたかったのが１つあったので、そういうふうに確認できたので、これはいいと思います。","respondent":"青木都市開発課長","answer":"それと、将来の建て替えについてどのようなということは、昨日、実はまちづくり検討委員会の皆様からもご質問いただいたところなんですけれども、冒頭申し上げましたとおり、今回の地区計画の指定というのは、区の本旨としては。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、それについてはよくわかるし、私自身も住んでいるところで、そういうふうに見ていただいているということがあれなんですけれども、ですから、しっかりと良好な環境を緑も含めて守って、さらにきちんと保全されていくような方向で、区としても支援をしていただきたいと思っているわけです。とりあえず以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"先ほどの説明を聞いていても、私自身もこの独特の言い回しといいますか、言葉の問題も含めて、これを一度で理解しろという、そういうふうに言ったというつもりはないですけど、そう言われてもわからないというのが率直な感情だと思いますので、地域への説明、住民の参加の保証のところについて、区の姿勢をちょっと伺いたいと思うんですけれども、先ほど、１２月８日、説明会だとか。","respondent":"岩田まちづくり事業部長","answer":"したがって、国のほうもそういった建て替えを促進するための法律はできましたけれども、なかなか進んでいませんので、いろいろ法律も変わっていくでしょうし、それを支援する制度というのも当然、今後２０年間には出てきますので。","voiceIndex":10,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"その素案の仕組み、原案のつくり、都市計画審議会、なかなかやっぱりなじみのないところではありますので、その都市計画、地区計画、学校のところで話がありましたけれども、なかなかその仕組みそのものがわからないと、公告・縦覧、意見を取り上げても、なじみがないですから、ぜひそういうところは仕組みがわからないと意見も言えないと思うので、ご説明を丁寧にお願いしたいなと思います。","respondent":"青木都市開発課長","answer":"すみません、法律用語的な運用になってしまいますけれども、保全というのは先ほど私、方針のところでご説明したとおり、今あるものを守っていきたいという思いを保全という言葉で、おおむね表現しています。","voiceIndex":12,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"何か確保というと、斜めから見ると、あればいい的な、そんなイメージではやっぱりだめで、今ある住環境をしっかりととらえる必要があるのかなと思ったので、ちょっと伺ったんです。ひっくり返せば建ててもいいですよという意味なのか、ちょっとここをご説明いただきたいのと、あと現状の一団地計画では、ここで言っている４、５、６というのはつくっちゃいけないんですよね。","respondent":"青木都市開発課長","answer":"改めて４ページの表の見方です。委員ご指摘のとおり、生活関連地区Ａ、生活関連地区Ｂと、生活利便・住宅地区においては、ここの表で書いてあります３から６についても、建築が可能という地区計画になってあります。","voiceIndex":14,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"ということは、この生活関連地区Ａと生活関連地区Ｂと、生活利便・住宅地区では、公衆浴場、工場、ボーリング場などのこういう施設、ホテルというのが今後建てられるようになるわけですね。そうした理由をちょっと教えていただけますか。","respondent":"青木都市開発課長","answer":"あるいはボーリング場、スケート場なども、まちづくり検討委員会からのご提言では、いろいろとスポーツ施設のようなことも積極的にご提案いただいておりましたので、将来にわたって、そういったものへの転用の可能性も残しておきたいという思いを込めまして。","voiceIndex":16,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"一番初めの「居住環境を将来にわたって保全」というところと、何かここがちょっとうまく理解できないなと思ってはいるんですけど、例えばこういうように、ホテル、旅館というふうにすると、どんなものなのか、まださっぱりわからないですけれども、ビジネスホテルなのか、それとももうちょっとワンランク上というんでしょうか、別のホテルなのか、あれですけれども、今、ないところから工場だったり、ホテル。","respondent":"青木都市開発課長","answer":"それと、例えば今、ご指摘がありました、ホテル、旅館等につきましても、現実にまちづくり検討委員会、地元の皆様からのご提言の中では、福祉施設に併設して、付き添いの方々が宿泊できるようなものが欲しいというご要望もありましたので、たまたまこれは別の施策上。","voiceIndex":18,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"関連して聞きます。生活関連地区Ａと生活関連地区Ｂというのは、学校はわかりますよね。八潮北と八潮南のほうですね。それは、区のほうの所有というわけですね。それが、いろいろ協議はするでしょうけれども、区が管理できないという状況にもなり得る可能性もあるならば、かなり不安というのが、そこにあるのではないかなというふうに、これはいかがでしょうか。","respondent":"青木都市開発課長","answer":"ですので、賃貸住宅等の、あるいは商業施設、民間施設になります。これについては、ご指摘のとおり、この宗教施設や自動車教習所以外のものについては、一般の用途規制と同じ縛りしかありませんので、より細かな用途規制を誘導していこうということは難しいのは事実です。","voiceIndex":20,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"わかりました。ただ、これからどうなるかわからないのですね。その説明のときには、その不安をなるべく排除できるような形で、ご説明をしていただきたいなというのが要望になります。だけど、それが外れてしまったことによって、守られなくなる部分というのはないんですか。ないというふうにはっきりするのであれば、それはその話をしていただきたいなと思いますが、いかがでしょうか。","respondent":"青木都市開発課長、岩田まちづくり事業部長、日下部企画財政課長","answer":"本当にないかと言えば、本当にありません。ただ、１点違うことを、気をつけたものの言い方をしますけれども、一団地の住宅施設の決定権限は東京都です。いわゆる通常の建築基準法上の用途規制、ここは住居地域なので、住居地域では、大きな工場とかそういったものはもともとできないんですね。したがいまして、本文のほうに戻りますが、こうした今、ご説明申し上げましたような検討の経過を踏まえまして、八潮南小学校。","voiceIndex":22,"id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"改めてそれぞれの学校、旧八潮南小学校、南中学校の敷地というか、建物の延べ床を教えていただきたいと思います。","respondent":"日下部企画財政課長","answer":"八潮南小学校、南中学校ともに、若干ちょっと違いますが、ほぼ６,０００m2です。","voiceIndex":28,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど地域の方に、昨日とかちょっと前とか、説明されたという話でしたけれども、どんなご意見があったのかと、その中身を教えていただきたいのと、あと今後の予定で、この使用開始のところ、まだはっきりしないとは思うんですけれども、これは何月なんですか。ちょっと現状で結構ですけど、上には８月と、こっちにはなかったので、ちょっと教えていただけますか。","respondent":"日下部企画財政課長","answer":"どんなご意見、ご質問があったかということですが、昨日のまちづくり検討委員会の中では、何人かの方からご意見をいただきましたが、主に施設計画にかかわることについて申し上げますと、１つは、八潮南中学校は高齢者施設、それから八潮南小学校が区民活動交流施設ということで。","voiceIndex":30,"id":"exchange-012"},{"speaker":"中塚委員","kind":"意見","question":"そこに住んでいる方も含め、区全体としても、そういう意味では今、課題を掘り起こして、もっと強化していかなければいけないという方向に進むべきだと思うんですけど、ここについて機能を維持するというところは、強化というのが必要じゃないかと思うんですけど、ちょっとここの中身のご説明をいただけますか。","respondent":"日下部企画財政課長","answer":"ですから、おっしゃるような維持・強化という、その辺の意味合いも含めたものとして受けとめていただきたいと思います。","voiceIndex":32,"id":"exchange-013"},{"speaker":"南委員","kind":"確認","question":"先ほどの最初のほうの説明で、６月２２日まで、一定程度の地域説明会をやってと、そこの関係で、改めてあれなんですけど、例えばこの区の施設を交流拠点と高齢者福祉施設を１日も早くつくってほしいという願いのもとなんですけど、これから地域説明をされていく中で、一定程度２月に公告・縦覧するということで、１２月８日に説明会が始まって、そういうスケジュールで始まっていくんですけれども。","respondent":"青木都市開発課長","answer":"もし万が一、意見書がいろいろ出て、この都市計画手続がおくれますと、一団地の住宅施設として、八潮南小・中学校が小学校であり、中学校である用途以外に使えないという規定が残ってしまいますので、５月以降。","voiceIndex":34,"id":"exchange-014"}]},{"id":"topic-02","title":"安全・安心のまちづくりに関すること","agenda":"安全・安心のまちづくりに関すること","exchanges":[{"speaker":"稲川委員","kind":"質問","question":"ちょっと数字的なものをお伺いしたいんですけど、基本的にいろいろ密集、密集と言うんですけれども、まず東京都の密集住宅の平均値と、あと密集というのはどこから密集になるのかというのをまず２点。密集住宅市街地整備促進事業、この２ページに終了地区とあるんですけど、事業はやられているというのはわかるんですが、この事業をやって、これで密集が解消されているのかどうなのか。","respondent":"吉川住環境整備担当課長","answer":"密集ということのとらえ方ですが、資料の１ページをごらんいただきたいんですが、防災まちづくりの観点から言うと、１ページの要件のところをごらんいただきたいんですが、事業要件にとらえておりますように、住宅戸数密度が１ha当たり３０戸以上。","voiceIndex":40,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"この前の委員会で視察もさせていただいて、戸建てがあったり、木造のアパートがあったり、密集と言われるところにはいろいろな形の住宅があり、それぞれ抱えている問題も複雑に絡み合っているんだなというのを実感したんですけれども、その中でお伺いしたいのは、いわゆる土地も自分のもの、建物も自分のもの。答えは１つではないとは思うんですけれども、ちょっと感じたものですから、ご説明いただけますか。","respondent":"吉川住環境整備担当課長","answer":"密集事業で老朽住宅の建て替えというのが事業の大きな柱の１つですが、なかなか進みにくいという現状がございまして、その理由としましては、ただいま委員がご指摘いただいたように、権利関係が複雑であったり、やはり高齢者の方が多くて。","voiceIndex":42,"id":"exchange-016"},{"speaker":"中塚委員","kind":"提案","question":"今の課長のお話ですけど、新しい住み方を提案している、ちょっとどういう内容なのか、そこを教えていただきたいと思うんですけれども、後半には具体的なことは課題だというお話でしたけれども、どんな問題意識があるのか、ちょっとその問題意識の中身を教えていただきたい。一方で、立ち退きを求められた高齢者に限って言えば、高齢者住宅がある。高齢者住宅を申し込んでも、とても難しい。","respondent":"吉川住環境整備担当課長、岩田まちづくり事業部長","answer":"ちょっとそれ以外のところでは、なかなか現在のところは今後の課題という、先ほどの回答と同じになってしまうんですが、そういったことでよろしくお願いいたします。だけれども、ストレートにそれを公的住宅、低所得者向けの公営住宅ですべて救済していくという考え方は事業費も含めて、非常に難しいというお答えで、今回はとどめします。","voiceIndex":44,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"具体的には難しい。それに対して今の制度や、今の中身が不十分だと。高齢者住宅、区営住宅、また木造の耐震診断、補強、建て替え、そういうこの辺の充実を図っていかないと、とても耐震改修促進計画に掲げた目標を見ているだけで進まないという、この課題の溝をどう埋めていくのかという姿勢が問われると思うんですよね。やっぱり姿勢は問いたいと思うんですけど、いかがでしょうか。","respondent":"岩田まちづくり事業部長","answer":"現に住宅に困窮している人たちのサポートもちゃんとやる。そういう新たな仕組みを来年度からできないか、今、検討していますので、品川区としても独自性を出しながら、この住宅対策というのは今後も進めてまいります。","voiceIndex":47,"id":"exchange-018"},{"speaker":"山内委員","kind":"質問・要望","question":"これはどう考えたって、新築は無理だろうというような場所に、ちょっとセットバックをして２軒建っているのを今でも覚えているんですが、住民の方が防災という観点を抜きに、自分たちが住みやすいという住環境を求めて、ああいう建て方をしちゃうと、品川区が一生懸命取り組んでいる防災についてというのは、ある意味、無意味になってしまうような、そういう思いをしたんですけれども。","respondent":"吉川住環境整備担当課長、片田建築課長","answer":"具体的な地区が挙がりましたので、そこの地区の現在の取り組み状況について、まずご説明しますと、密集事業地区では、まずあそこは東中延地区ということで行っておりまして。そうすると、表できちっと道路との接道がとれるということも含めて、地域の権利者の関係の方々が協力し合って、共同建替とか、そういう形での法制度もきちっと活用できるようなところでの協議が必要かなと思いますので、今。","voiceIndex":49,"id":"exchange-019"},{"speaker":"山内委員","kind":"質問","question":"ほかのあの周りの住民の方々、いわゆる町会を含めたものでしょうけど、そういう方々のやりとりというか、コミュニケーションというのはどういう形でしょうか。もちろん、あそこは万が一何かあったときには、周りも被害をこうむるようなことも考えられなくはないと思うんですけれども、そういう周りの人たちの防災に対する意識のコミュニケーションというのはどういう形でなされているのでしょうか。","respondent":"吉川住環境整備担当課長","answer":"実際のコミュニケーションにつきましても、あそこの同潤会の地区の中でもメンバーに入っている方がいらっしゃいますので、その方を通じて一定のコミュニケーションが図られているのではないかと考えているところです。","voiceIndex":52,"id":"exchange-020"},{"speaker":"山内委員","kind":"質問","question":"わかりました。１点。建築課長にお尋ねします。先ほど、あそこは２項道路の指定がないということで説明いただいたんですが、２項道路の指定がないというのはどういうことなんですか。","respondent":"片田建築課長、岩田まちづくり事業部長","answer":"なおかつ、２項道路の要件に該当する場所については、先ほどの住宅が個別に建て替えられたり、建築確認を受けてありますので、問題なのはそういう地域について、今後あそこの場所だけではございませんけれども。したがって、これを急ぐと、ボタンのかけ違いでこじれてしまってだめになってしまうというのもありますから、やはりきちっ、きちっと、時間をかけないほうがいいんですけども、時間をかけながら。","voiceIndex":54,"id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"アンケートというのはどういう内容のアンケートだったのですか。","respondent":"吉川住環境整備担当課長","answer":"都市防災不燃化促進事業を導入することについてのアンケートですので、まず基本的なところから、このまちに対する意識、要するに災害に対する危険性をどのように考えていますかといった一般的な質問から入りまして、それから不燃化促進事業を行いたいということですので。","voiceIndex":59,"id":"exchange-022"},{"speaker":"大沢委員","kind":"質問・要望","question":"今日、各事業についての制度の説明ということでお伺いはしたんですが、そういう説明ということで、事業についてちょっと伺いたいと思うんですけれども、このように３つ事業があるんですが、この事業内容で、道路整備と公園・広場整備というのが重複している箇所があるんですが、これはどのような状態で、どのような場合に応じて切り分けをし、使い分けをしているのか、伺わせていただきたいと思います。","respondent":"吉川住環境整備担当課長","answer":"事業の実際の内容といたしましては道路整備、公園・広場整備、それぞれ内容的には同じです。どの事業で行って、どの補助金をもらうかというところが違うとご理解いただければと思います。","voiceIndex":61,"id":"exchange-023"},{"speaker":"大沢委員","kind":"質問","question":"それはどこでどういうふうな判断をして、使い分け、切り分けをしているんですかということを伺ったんです。目的が違うということですよね。目的が違うということで、この使い分けをしているということですけれども、富士見通りと林試の森のところでも、公園整備はおのおのの目的が違っても、我々一般には見えてこない。同じような整備に見えるんですが。","respondent":"岩田まちづくり事業部長","answer":"公園につきましては、これは両事業とも、防災活動広場と言われている、いわゆる防災活動のための小公園という形で、広場中心の公園として全部整備をしております。これは全く同じものです。","voiceIndex":63,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6378#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":36220,"voices":69}},{"id":"h20-20081205-9","meetingId":"h20-cm12","date":"2008年12月5日","dateIso":"2008-12-05","committee":"文教委員会","time":"午後１時５８分～午後２時１０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第９５号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例","agenda":"第９５号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"支給額そのものは変わらないという説明だと思うんですけれども、手取りというんですか、そこではどんなふうに変わっていくのか教えてください。最後に、将来受け取る年金というのにどのように影響するのか教えてください。","respondent":"田村庶務課長","answer":"地域手当の関係です。１点目の地域手当は、平成１８年４月１日から、いわゆる調整手当という言い方をしていたのですが、それを地域手当に変更したと。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１つだけ伺います。これは平成２２年度までは人事委員会勧告もあって、こういう形でいいんですが、私は独自採用も含めて、いろいろ教員も区で独自に、品川区がどういうやり方をしたって、法的には……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"１級、２級、３級、それから号給はどういう形で上がっていくのかという仕組みですね。ずっとかなり細かいものがあるので。１年ごとに上がっていくというものではないと思っているのですが、どういう形で上がっていくのかということをお聞きしたいです。","respondent":"河野指導課長","answer":"それから昇給のほうですが、こちらのほうが基本的には１年間で４号給昇給。ただし、成績率その他でこれが１号給になったり、場合によっては６号給になるということで、勤務実績によって変化をいたします。","voiceIndex":14,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり独自採用ということもありますし、そもそも給与自体をどう考えるか、評価も絡んでくる話だと思いますので、その評価に対してそれなりの評価、報酬というのもしかるべきではないかと思いますので、できれば品川区の中でプラスアルファというところを考えていただきたいと思います。要望ということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-004"},{"speaker":"中塚委員","kind":"意見","question":"１点だけなんですけど、私は区の独自採用の人も、今までの幼稚園の先生の方も待遇というのは同じであるべきだと思います。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4654#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":3601,"voices":21}},{"id":"h20-20081205-5","meetingId":"h20-cm12","date":"2008年12月5日","dateIso":"2008-12-05","committee":"総務委員会","time":"午後１時５８分～午後２時２１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"民間との差が７５円ということなんですけれども、こんな経済状況下なのでかなり給料も厳しいかと思うんですけれども、こんな７５円の差なんてと思うので、どういう企業を調査したのか、どのぐらいの調査、規模でしたのか。たしか、前にいただいたこともあったような気もしたんですけれども、ちょっと教えていただきたいのと、調査の仕方、どういう調査をしたのかという２点を伺います。","respondent":"榎本人事課長","answer":"前回の総務委員会で、人事委員会勧告の概要でご報告したところですけれども、民間との調査の内容につきましては、平成２０年４月１日現在、平成２０年４月分の給料で公務員の給料、民間企業の給料を比べているものです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"たしか、大企業がトップにあって５％程度で、あとは中小企業、三角形のピラミッド型で見たときに、圧倒的に中小企業、下のほうの零細、小規模の事業所というピラミッドが日本の企業の体系としてあると思っているんですけど、公務員の場合、大企業との差が５％以上ついたときに人勧がというふうな記憶があるんですが、相当前の話で、そういうことというのはずっと人勧の調査というのは。","respondent":"榎本人事課長","answer":"それ以外は５％を超えていることはないので、特に５％を超えたからという形ではないです。企業規模につきましては、前は１００人以上の規模だけでやっていたものを、たしか一昨年から５０人以上という企業規模を入れまして、カバー率を６割台から７割台に上げたという形です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"５０人規模というとある程度小さいところですので、そういうところを入れることが本当に果たしてというのは、私は思うんです。しかし、特にこういう不況下ですから、給料が比較にならないと思うので、そういう意見を私は持ったということで表明しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"林委員","kind":"質問","question":"こういうことを前から言っているんだけど、人事委員会からここに出てくると、ああ、そうですか、これでいきましょう、はい、やりましょうと言って、さっきも言ったけど、上がったようで上がらないからいいんだと、かえって退職金ではマイナスの数字が出るんだ、だから、こういうものを見ながら世の動きみたいなものを区トップの人たちはきちんと見るのかどうか。","respondent":"榎本人事課長","answer":"今回は人勧なしということですけれども、この間、人勧のマイナスが今までに４回ほど実施してきております。","voiceIndex":10,"id":"exchange-004"},{"speaker":"林委員","kind":"質問","question":"だけど、自治体、行政というのは、品川区も早くからサービス産業、サービス業であるという一つの思いを取り入れていろいろなところで行革を進めたりしてきて、ただ、物を売って利益を得るものではないわけですから、景気が悪くなってきたって、いきなり収入を増やしていくというのはなかなか難しいとすれば、備えあればということばかりやっていてもしようがないんだけれども。","respondent":"福田企画部長","answer":"それで私ども、予算編成の過程になるわけですが、もちろん行政には継続性がありますので、やるべきことはやる、それから新規事業につきましても、これまで区民の皆様がお待ちになっている事業が多うありますので、それについてもできるだけ予算的な措置は講じてまいりたいと。","voiceIndex":12,"id":"exchange-005"},{"speaker":"林委員","kind":"意見","question":"自治体は単年度決算だからスパンスパンと、１２月あるいは３月で切っていってしまうということで、数字がそこで一たん出てしまうので、企業の場合は赤字が出れば引きずっていかなければならないというようなこともあるので、そういった意味で、ぜひ多元的にいいからもう安泰だというのは、それはそれで非常に結構なことだけど、世界の成り行き。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":14,"id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"反対するものではありませんけれども、今意見が出たように世の中大変不景気ですね。景気は内需拡大の方向に、必要だというふうに広く指摘されていながらなかなかそうふうには政治が向いていかないというところで、公務員のこの給料も実質的には支給される額は変わらないけれども、将来的に見て、基本給の率も下がってくるということですから、やはりここは問題があるのではないかと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1806#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":7050,"voices":23}}]);
